  function imbueMaterialList(key, tier, sets) {
    const rec = IMBU_RECIPES[key];
    if (!rec) return null;
    const t = (tier || 'powerful').toLowerCase();
    const mats = rec[t] || rec.powerful;
    const n = Math.max(1, parseInt(sets, 10) || 1);
    return mats.map(([name, qty]) => ({ name, qty: qty * n }));
  }

  // Clica no botão BUY da oferta mais barata (primeira linha com BUY).
  function clickCheapestBuy(name) {
    const rows = marketListingRows(name);
    if (!rows.length) return false;
    let node = rows[0];
    for (let i = 0; i < 10 && node; i++, node = node.parentElement) {
      if (!node.querySelectorAll) continue;
      // Botão BUY da linha (h5, button ou span)
      const buyBtn = Array.from(node.querySelectorAll('h5,button,span,p,div')).find(
        (el) => /^buy$/i.test((el.textContent || '').trim()) && visible(el)
      );
      if (buyBtn) { click(buyBtn); return true; }
    }
    const buy = byText('h5', 'BUY') || byText('button', 'BUY');
    if (buy && visible(buy)) { click(buy); return true; }
    return false;
  }

  // Modal "BUY LISTING" (quantidade + BUY laranja).
  function buyListingModal() {
    const title = Array.from(document.querySelectorAll('h4,h5,h3,p,div,span')).find(
      (el) => {
        const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
        return /^buy listing$/i.test(t) && visible(el);
      }
    );
    if (title) {
      let n = title.parentElement;
      for (let i = 0; i < 14 && n && n !== document.body; i++, n = n.parentElement) {
        if (n.querySelector && n.querySelector('input')) return n;
      }
    }
    const qtyLabel = Array.from(document.querySelectorAll('*')).find(
      (el) => {
        if (el.children && el.children.length > 3) return false; // só nós "folha de texto"
        const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
        return /^quantity$/i.test(t) && visible(el);
      }
    );
    if (qtyLabel) {
      let n = qtyLabel.parentElement;
      for (let i = 0; i < 12 && n && n !== document.body; i++, n = n.parentElement) {
        if (n.querySelector && n.querySelector('input') && /buy/i.test(n.textContent || '')) return n;
      }
    }
    return null;
  }

  function buyListingOpen() {
    return !!Array.from(document.querySelectorAll('h4,h5,h3,p,div,span')).find((el) => {
      const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
      return /^buy listing$/i.test(t) && visible(el);
    });
  }

  function buyListingQtyInput(modal) {
    modal = modal || buyListingModal();
    if (!modal) return null;
    const inputs = Array.from(modal.querySelectorAll('input')).filter(visible);
    // O do screenshot é um input com valor numérico (default 1)
    return inputs.find((inp) => {
      const v = String(inp.value ?? '').trim();
      return v === '' || /^\d+$/.test(v);
    }) || inputs[0] || null;
  }

  // Lê a quantidade atual no modal
  function readBuyListingQty() {
    const inp = buyListingQtyInput();
    if (!inp) return null;
    const n = parseInt(String(inp.value || '').replace(/\D/g, ''), 10);
    return Number.isFinite(n) ? n : null;
  }

  // The Market limits each purchase to the stock of the selected listing.
  function readBuyListingAvailable(modal) {
    modal = modal || buyListingModal();
    if (!modal) return null;
    const m = (modal.textContent || '').replace(/\s+/g, ' ').match(/([\d.]+)\s*x\s*available/i);
    if (!m) return null;
    const n = parseInt(m[1].replace(/\D/g, ''), 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }

  // Define quantidade: 1) digita no input  2) se falhar, clica no "+" N vezes
  async function setBuyQuantity(qty) {
    qty = Math.max(1, parseInt(qty, 10) || 1);
    const modal = buyListingModal();
    if (!modal) {
      log('Imbui-buy: setQty — modal não encontrado');
      return false;
    }
    const input = buyListingQtyInput(modal);
    if (input) {
      input.focus();
      await sleep(80);
      // Seleciona tudo e sobrescreve (melhor p/ React controlado)
      try {
        input.select();
        input.setSelectionRange(0, String(input.value || '').length);
      } catch (_) {}
      setNativeInput(input, String(qty));
      // reforço extra
      try {
        const nativeSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
        nativeSetter.call(input, String(qty));
        input.dispatchEvent(new InputEvent('input', { bubbles: true, data: String(qty), inputType: 'insertText' }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        input.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, key: 'Enter', keyCode: 13 }));
        input.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: 'Enter', keyCode: 13 }));
      } catch (_) {}
      await sleep(200);
      if (readBuyListingQty() === qty) {
        log(`Imbui-buy: setQty via input = ${qty} ✔`);
        return true;
      }
      log(`Imbui-buy: setQty input não pegou (valor=${input.value}) — tentando botões +/-`);
    }

    // Estratégia 2: botão MAX se qty for o máximo disponível
    const availMatch = (modal.textContent || '').match(/(\d+)\s*x\s*available/i);
    const available = availMatch ? parseInt(availMatch[1], 10) : null;
    const maxBtn = Array.from(modal.querySelectorAll('button,div,span,p,h5')).find(
      (el) => /^max$/i.test((el.textContent || '').trim()) && visible(el)
    );
    if (maxBtn && available && qty >= available) {
      click(maxBtn);
      await sleep(250);
      if (readBuyListingQty() === available || readBuyListingQty() === qty) {
        log(`Imbui-buy: setQty via MAX = ${readBuyListingQty()} ✔`);
        return true;
      }
    }

    // Estratégia 3: clicar "+" a partir de 1
    // Reseta para 1 se possível
    if (input) {
      setNativeInput(input, '1');
      await sleep(150);
    }
    const plusBtn = Array.from(modal.querySelectorAll('button,div,span')).find((el) => {
      const t = (el.textContent || '').trim();
      return (t === '+' || t === '＋') && visible(el);
    });
    // Às vezes o + é só um ícone SVG sem texto — procura botão ao lado do input
    let plus = plusBtn;
    if (!plus && input) {
      const row = input.parentElement;
      if (row) {
        const btns = Array.from(row.querySelectorAll('button,div[role="button"],span')).filter(visible);
        // ordem visual: - input + MAX  → o que está à direita do input
        const ir = input.getBoundingClientRect();
        plus = btns.find((b) => {
          const r = b.getBoundingClientRect();
          return r.left >= ir.right - 4 && r.width < 60 && r.height < 60;
        }) || null;
      }
    }
    if (plus) {
      const cur0 = readBuyListingQty() || 1;
      const need = qty - cur0;
      for (let i = 0; i < need; i++) {
        click(plus);
        await sleep(60);
      }
      await sleep(150);
      const got = readBuyListingQty();
      if (got === qty) {
        log(`Imbui-buy: setQty via + = ${qty} ✔`);
        return true;
      }
      log(`Imbui-buy: setQty via + ficou em ${got}, queria ${qty}`);
    } else {
      log('Imbui-buy: setQty — botão + não encontrado');
    }
    return readBuyListingQty() === qty;
  }

  // Clica o BUY laranja DENTRO do modal (não o da lista de ofertas).
  function clickConfirmBuy() {
    const modal = buyListingModal();
    const root = modal || document.body;

    // 1) button cujo texto normalizado é só "BUY"
    let candidates = Array.from(root.querySelectorAll('button')).filter((el) => {
      if (!visible(el)) return false;
      const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
      return /^buy$/i.test(t);
    });

    // 2) qualquer elemento clicável com texto BUY curto dentro do modal
    if (!candidates.length) {
      candidates = Array.from(root.querySelectorAll('button,div,span,h5,p')).filter((el) => {
        if (!visible(el)) return false;
        const t = (el.textContent || '').replace(/\s+/g, ' ').trim();
        return /^buy$/i.test(t);
      });
    }

    // 3) Preferir o que está na metade inferior do modal (barra de ação)
    if (candidates.length > 1 && modal) {
      const mr = modal.getBoundingClientRect();
      const midY = mr.top + mr.height * 0.45;
      const lower = candidates.filter((el) => el.getBoundingClientRect().top >= midY);
      if (lower.length) candidates = lower;
    }

    if (!candidates.length) {
      log('Imbui-buy: confirmBuy — nenhum BUY no modal');
      return false;
    }

    // Pega o de maior área (botão real, não label pequeno)
    candidates.sort((a, b) => {
      const ra = a.getBoundingClientRect();
      const rb = b.getBoundingClientRect();
      return (rb.width * rb.height) - (ra.width * ra.height);
    });
    const btn = candidates[0];
    log(`Imbui-buy: confirmBuy clicando <${btn.tagName.toLowerCase()}> "${(btn.textContent || '').trim()}"`);
    click(btn);
    // clique extra no centro caso o handler esteja no pai
    try {
      const parent = btn.parentElement;
      if (parent && parent !== modal) {
        const t = (parent.textContent || '').replace(/\s+/g, ' ').trim();
        if (/buy/i.test(t) && t.length < 20) click(parent);
      }
    } catch (_) {}
    return true;
  }

  // Compra qty unidades do item no floor price.
  async function buyMarketItem(name, qty) {
    qty = Math.max(1, parseInt(qty, 10) || 1);
    log(`Imbui-buy: comprando ${qty}× "${name}"...`);
    if (!(await autoListPart1(name))) {
      log(`Imbui-buy: ✖ não consegui abrir/selecionar "${name}"`);
      return { ok: false, name, qty, error: 'seleção falhou' };
    }
    const unit = marketCheapestPrice(name);
    if (unit === null) {
      log(`Imbui-buy: ✖ sem oferta de "${name}" no market`);
      return { ok: false, name, qty, error: 'sem oferta', unit: null };
    }
    log(`Imbui-buy: floor de "${name}" = ${fmtGold(unit)} → total ~ ${fmtGold(unit * qty)}`);

    // Fecha modal residual se ainda estiver aberto de uma tentativa anterior
    if (buyListingOpen()) {
      const modal = buyListingModal();
      const x = modal && modal.querySelector('svg[viewBox="0 0 14 14"]');
      if (x) { click(x); await sleep(400); }
    }

    // 1) Clica BUY na listagem
    if (!clickCheapestBuy(name)) {
      log(`Imbui-buy: ✖ não achei o botão BUY de "${name}"`);
      return { ok: false, name, qty, unit, error: 'BUY não encontrado' };
    }

    // 2) Espera o modal BUY LISTING abrir
    let opened = false;
    for (let t = 0; t < 15; t++) {
      await sleep(350);
      if (buyListingOpen()) { opened = true; break; }
    }
    if (!opened) {
      log(`Imbui-buy: ✖ modal BUY LISTING não abriu`);
      return { ok: false, name, qty, unit, error: 'modal não abriu' };
    }
    log(`Imbui-buy: modal BUY LISTING aberto ✔`);
    await sleep(400);

    // 3) Define quantidade (input e/ou botão +)
    const available = readBuyListingAvailable();
    const targetQty = available === null ? qty : Math.min(qty, available);
    if (available !== null && available < qty) {
      log(`Imbui-buy: oferta atual tem apenas ${available}x; faltarao ${qty - available}x`);
    }
    if (!targetQty) return { ok: false, name, qty, unit, error: 'oferta sem estoque', bought: 0 };
    const qtyOk = await setBuyQuantity(targetQty);
    const gotQty = readBuyListingQty();
    const bought = Math.max(0, Math.min(targetQty, parseInt(gotQty, 10) || 0));
    log(`Imbui-buy: quantidade no modal = ${gotQty} (alvo ${targetQty}) ${qtyOk ? '✔' : '⚠'}`);
    if (!bought) return { ok: false, name, qty, unit, error: 'quantidade invalida no modal', bought: 0 };
    await sleep(350);

    // 4) Confirma BUY no modal
    if (!clickConfirmBuy()) {
      log(`Imbui-buy: ✖ não achei o BUY de confirmação no modal`);
      return { ok: false, name, qty, unit, error: 'confirm BUY falhou' };
    }

    // 5) Espera o modal fechar
    let closed = false;
    for (let t = 0; t < 12; t++) {
      await sleep(400);
      if (!buyListingOpen()) { closed = true; break; }
    }
    if (!closed) {
      // tenta clicar BUY de novo uma vez
      log(`Imbui-buy: modal ainda aberto — segundo clique em BUY`);
      clickConfirmBuy();
      for (let t = 0; t < 8; t++) {
        await sleep(400);
        if (!buyListingOpen()) { closed = true; break; }
      }
    }
    if (!closed) {
      log(`Imbui-buy: ⚠ modal ainda aberto após BUY — compra pode não ter ido`);
      // fecha pra não travar o próximo item
      const modal = buyListingModal();
      const x = modal && modal.querySelector('svg[viewBox="0 0 14 14"]');
      if (x) click(x);
      await sleep(300);
      return { ok: false, name, qty, unit, error: 'modal não fechou' };
    }
    log(`Imbui-buy: ✔ compra confirmada — ${bought}× "${name}" @ ${fmtGold(unit)}`);
    return { ok: true, name, qty, bought, unit, subtotal: unit * bought };
  }

  // A material may span multiple listings. Reopen the item after every
  // successful listing purchase until the requested total is complete.
  async function buyMarketItemTotal(name, qty) {
    const requested = Math.max(1, parseInt(qty, 10) || 1);
    let remaining = requested;
    let spent = 0;
    let lastUnit = null;
    let attempts = 0;
    const purchases = [];
    while (remaining > 0 && attempts++ < 25) {
      const r = await buyMarketItem(name, remaining);
      if (!r.ok || !(r.bought > 0)) {
        return { ok: false, name, qty: requested, bought: requested - remaining, remaining,
          subtotal: spent, unit: lastUnit, purchases, error: r.error || 'compra incompleta' };
      }
      purchases.push(r);
      remaining -= r.bought;
      spent += r.subtotal || 0;
      lastUnit = r.unit;
      if (remaining > 0) {
        log(`Imbui-buy: ${r.bought}x compradas; procurando outra oferta para ${remaining}x de "${name}"...`);
        await sleep(250);
      }
    }
    if (remaining > 0) {
      return { ok: false, name, qty: requested, bought: requested - remaining, remaining,
        subtotal: spent, unit: lastUnit, purchases, error: 'limite de tentativas ao procurar oferta' };
    }
    return { ok: true, name, qty: requested, bought: requested, remaining: 0,
      subtotal: spent, unit: lastUnit, purchases };
  }

  // Cota todos os materiais sem comprar.
  async function quoteImbue(key, tier, sets) {
    const mats = imbueMaterialList(key, tier, sets);
    if (!mats) return { ok: false, error: 'imbuement desconhecido' };
    const items = [];
    let total = 0;
    let missing = 0;
    for (const m of mats) {
      if (!(await autoListPart1(m.name))) {
        items.push({ ...m, unit: null, subtotal: null, error: 'não encontrado' });
        missing++;
        continue;
      }
      const unit = marketCheapestPrice(m.name);
      if (unit === null) {
        items.push({ ...m, unit: null, subtotal: null, error: 'sem oferta' });
        missing++;
      } else {
        const subtotal = unit * m.qty;
        total += subtotal;
        items.push({ ...m, unit, subtotal, error: null });
        log(`Imbui-quote: ${m.qty}× ${m.name} @ ${fmtGold(unit)} = ${fmtGold(subtotal)}`);
      }
      await sleep(400);
    }
    return { ok: missing === 0, items, total, missing, key, tier, sets };
  }

  let imbueBusy = false;

  async function runImbueQuote() {
    if (imbueBusy) return;
    imbueBusy = true;
    try {
      const key = cfg.imbueKey || 'Strike';
      const tier = cfg.imbueTier || 'powerful';
      const sets = cfg.imbueSets || 1;
      log(`Imbui-quote: ${key} / ${tier} ×${sets}`);
      const res = await quoteImbue(key, tier, sets);
      closeMarketWindow();
      if (ui && ui.imbueResult) {
        const lines = (res.items || []).map((it) => {
          if (it.error) return `• ${it.qty}× ${it.name}: ${it.error}`;
          return `• ${it.qty}× ${it.name}: ${fmtGold(it.unit)} → ${fmtGold(it.subtotal)}`;
        });
        lines.push('');
        lines.push(res.ok
          ? `Total: ${fmtGold(res.total)}`
          : `Total parcial: ${fmtGold(res.total || 0)} (${res.missing} item(ns) sem oferta)`);
        ui.imbueResult.textContent = lines.join('\n');
      }
      if (res.ok) {
        notify(`💰 Imbui ${key} (${tier}): total ${fmtGold(res.total)}`);
        log(`Imbui-quote: total ${fmtGold(res.total)}`);
      } else {
        notify(`⚠ Cotação incompleta — veja o painel`);
      }
      return res;
    } catch (e) {
      log('Imbui-quote: erro — ' + (e && e.message ? e.message : e));
      return { ok: false, error: String(e) };
    } finally {
      imbueBusy = false;
    }
  }

  async function runImbueBuy() {
    if (imbueBusy) return;
    imbueBusy = true;
    try {
      const key = cfg.imbueKey || 'Strike';
      const tier = cfg.imbueTier || 'powerful';
      const sets = cfg.imbueSets || 1;
      const budget = Math.max(0, parseInt(cfg.imbueMaxBudget, 10) || 0);
      log(`Imbui-buy: ${key} / ${tier} ×${sets}` + (budget ? ` (orçamento ${fmtGold(budget)})` : ''));

      // Compra direta: a cotação é exclusiva do botão de consulta. Assim que
      // o usuário pede compra, cada material é buscado e comprado na sequência.
      const mats = imbueMaterialList(key, tier, sets);
      if (!mats) return { ok: false, error: 'imbuement desconhecido' };
      if (budget > 0) log(`Imbui-buy: orçamento configurado em ${fmtGold(budget)} (compra direta, sem cotação prévia)`);

      // Compra item a item
      const results = [];
      for (const it of mats) {
        const r = await buyMarketItemTotal(it.name, it.qty);
        results.push(r);
        await sleep(250);
      }
      closeMarketWindow();
      const okN = results.filter((r) => r.ok).length;
      const spent = results.reduce((s, r) => s + (r.ok ? (r.subtotal || 0) : 0), 0);
      log(`Imbui-buy: finalizado — ${okN}/${results.length} ok, gasto ~ ${fmtGold(spent)}`);
      notify(`🛒 Imbui: ${okN}/${results.length} itens comprados (~ ${fmtGold(spent)})`);
      if (ui && ui.imbueResult) {
        ui.imbueResult.textContent =
          results.map((r) => r.ok
            ? `✔ ${r.bought || r.qty}× ${r.name} (total completo)`
            : `✖ ${r.name}: ${r.error || 'falhou'}${r.bought ? ` (${r.bought}/${r.qty} compradas; faltam ${r.remaining})` : ''}`
          ).join('\n') + `\n\nGasto estimado: ${fmtGold(spent)}`;
      }
      return { ok: okN === results.length, results, spent, quote: null };
    } catch (e) {
      log('Imbui-buy: erro — ' + (e && e.message ? e.message : e));
      try { closeMarketWindow(); } catch (_) {}
      return { ok: false, error: String(e) };
    } finally {
      imbueBusy = false;
    }
  }


  // as próximas partes (ler preços e criar a nossa listagem).
  let autoListBusy = false;

  const marketOpen = () => !!byText('h4', 'MARKET');

  // Raiz do modal do Market: sobe do <h4>MARKET até o ancestral que contém o
  // combo de item. O svg KeyboardArrowDownIcon é EXCLUSIVO desse combo (os
  // selects de Slot/Vocation/Rarity usam ArrowDropDownIcon) — âncora estável.
  function marketRoot() {
    const h = byText('h4', 'MARKET');
    if (!h) return null;
    let node = h;
    for (let i = 0; i < 12 && node; i++) {
      if (node.querySelector && node.querySelector('svg[data-testid="KeyboardArrowDownIcon"]')) return node;
      node = node.parentElement;
    }
    return null;
  }

  // Botão do Market na barra do topo (só existe na cidade). Clica no svg
  // interno (padrão React: o clique borbulha até o handler do container).
  function clickMarketButton() {
    const btn = document.querySelector('[aria-label="MARKET"]');
    if (!btn || !visible(btn)) return false;
    click(btn.querySelector('svg') || btn);
    return true;
  }

  const marketSearchInput = () => document.querySelector('input[placeholder="Search item"]');

  // Popup da busca de item: sobe do input até o container que também tem os
  // resultados (slots de item). Para antes do body pra não vazar pro resto
  // do documento (inventário etc.).
  function marketSearchPopup() {
    const inp = marketSearchInput();
    if (!inp) return null;
    let node = inp.parentElement;
    for (let i = 0; i < 8 && node && node !== document.body; i++) {
      if (node.querySelector('.stonegy-item-holder-slot')) return node;
      node = node.parentElement;
    }
    return null;
  }

  // Linhas de listagem do item na tabela do Market (h5 com o nome exato).
  function marketListingRows(name) {
    const want = name.trim().toLowerCase();
    return Array.from(document.querySelectorAll('h5')).filter(
      (h) => (h.textContent || '').trim().toLowerCase() === want && visible(h)
    );
  }

  // Abre o seletor de item do Market (a setinha do combo) e escolhe o item
  // pelo nome na busca. Serve tanto pro View Market ("Item selected") quanto
  // pro Create New Listing ("Select item") — os dois usam o mesmo popup, e o
  // KeyboardArrowDownIcon é a âncora nos dois casos.
  async function marketPickItem(name) {
    for (let t = 0; t < 3 && !marketSearchInput(); t++) {
      const root = marketRoot();
      const arrow = root && root.querySelector('svg[data-testid="KeyboardArrowDownIcon"]');
      const alvo = arrow || byText('p', 'Item selected') || byText('p', 'Select item');
      if (alvo) { log('Auto-listagem: abrindo o seletor de item'); click(alvo); }
      else log('Auto-listagem: seletor de item não encontrado');
      await sleep(700);
    }
    const inp = marketSearchInput();
    if (!inp) { log('Auto-listagem: ✖ a busca de item não abriu'); return false; }

    // Digita o nome (input controlado: setter nativo + eventos) e espera filtrar.
    setNativeInput(inp, name);
    log(`Auto-listagem: buscando "${name}"...`);
    await sleep(1000);

    // Clica no item filtrado dentro do popup (o <p> com o nome; fallback: o
    // sprite via aria-label — o clique sintético borbulha mesmo com
    // pointer-events:none no span).
    const popup = marketSearchPopup();
    const want = name.trim().toLowerCase();
    let alvoItem = null;
    if (popup) {
      alvoItem = Array.from(popup.querySelectorAll('p')).find(
        (p) => (p.textContent || '').trim().toLowerCase() === want && visible(p)
      ) || Array.from(popup.querySelectorAll('span[aria-label]')).find(
        (s) => (s.getAttribute('aria-label') || '').trim().toLowerCase() === want
      );
    }
    if (!alvoItem) { log(`Auto-listagem: ✖ item "${name}" não apareceu na busca (o nome precisa ser exato)`); return false; }
    click(alvoItem);
    await sleep(900);
    return true;
  }

  // PARTE 1: Market aberto + item buscado + listagens na tela.
  async function autoListPart1(name) {
    // 1) Abre o Market (o botão só existe na cidade).
    for (let t = 0; t < 3 && !marketOpen(); t++) {
      log(`Auto-listagem: abrindo o Market (tentativa ${t + 1})`);
      if (!clickMarketButton()) log('Auto-listagem: botão do Market não encontrado — você está na cidade?');
      await sleep(900);
    }
    if (!marketOpen()) { log('Auto-listagem: ✖ o Market não abriu'); return false; }
    log('Auto-listagem: Market aberto ✔');

    // 1b) Se o Market ficou na aba My Listings (item anterior), volta pra
    //     View Market — o combo "Item selected" só existe lá.
    if (byText('p', 'CREATE NEW LISTING')) {
      const tab = byText('p', 'View Market');
      if (tab) { log('Auto-listagem: voltando pra aba View Market'); click(tab); await sleep(800); }
    }

    // 2) Seleciona o item no "Item selected".
    if (!(await marketPickItem(name))) return false;
    log('Auto-listagem: item clicado — carregando listagens...');

    // 3) Aguarda as listagens carregarem (linhas h5 com o nome do item).
    for (let t = 0; t < 8; t++) {
      await sleep(600);
      const rows = marketListingRows(name);
      if (rows.length) {
        log(`Auto-listagem: ${rows.length} listagem(ns) de "${name}" no mercado`);
        return true;
      }
    }
    log('Auto-listagem: ⚠ item selecionado, mas sem listagens à venda (sem preço de referência)');
    return true; // a seleção funcionou; ausência de listagens não é falha do fluxo
  }

  // Preço da PRIMEIRA linha de listagem do item (o jogo ordena do mais barato
  // pro mais caro → a primeira é o floor price). Sobe do h5 do nome até o
  // container da linha (o que tem o botão BUY) e lê o <p> numérico (preço).
  function marketCheapestPrice(name) {
    const rows = marketListingRows(name);
    if (!rows.length) return null;
    let node = rows[0];
    for (let i = 0; i < 8 && node; i++, node = node.parentElement) {
      if (!node.querySelectorAll) continue;
      const hasBuy = Array.from(node.querySelectorAll('h5')).some(
        (h) => /^buy$/i.test((h.textContent || '').trim())
      );
      if (!hasBuy) continue;
      const priceP = Array.from(node.querySelectorAll('p')).find((p) => {
        const t = (p.textContent || '').trim();
        return /^[\d.]+$/.test(t) && /\d/.test(t);
      });
      if (priceP) {
        const n = parseInt((priceP.textContent || '').replace(/\D/g, ''), 10);
        return Number.isFinite(n) ? n : null;
      }
    }
    return null;
  }

  // Preços das NOSSAS listagens do item (aba My Listings). Cada linha nossa
  // tem o botão CANCEL e o texto "Common - 26x - 62 each" — extraímos o
  // "62 each". Usado pra saber se o floor price já é nosso (não undercutar a
  // própria oferta).
  function myListingPrices(name) {
    const out = [];
    marketListingRows(name).forEach((h) => {
      let node = h;
      for (let i = 0; i < 6 && node; i++, node = node.parentElement) {
        if (!node.querySelectorAll) continue;
        const hasCancel = Array.from(node.querySelectorAll('h5')).some(
          (x) => /^cancel$/i.test((x.textContent || '').trim())
        );
        if (!hasCancel) continue;
        const p = Array.from(node.querySelectorAll('p')).find(
          (el) => /each\s*$/i.test((el.textContent || '').trim())
        );
        if (p) {
          const m = (p.textContent || '').match(/-\s*([\d.]+)\s*each/i);
          if (m) out.push(parseInt(m[1].replace(/\./g, ''), 10));
        }
        break;
      }
    });
    return out;
  }

  // Quantidade máxima do "(Max. N)" ao lado do campo Quantity. N = quanto do
  // item temos disponível. Retorna null se 0 / não encontrado (guarda contra
  // listar sem item selecionado).
  function listingMaxQty() {
    const p = Array.from(document.querySelectorAll('p')).find(
      (el) => /^\(Max\.\s*[\d.]+\)$/i.test((el.textContent || '').trim()) && visible(el)
    );
    if (!p) return null;
    const n = parseInt((p.textContent || '').replace(/\D/g, ''), 10);
    return Number.isFinite(n) && n > 0 ? n : null;
  }

  // PARTE 2: lê o floor price, vai em My Listings e cria a listagem por
  // (floor − 1) com a quantidade máxima — nossa listagem vira o floor.
  async function autoListPart2(name) {
    // A) Market aberto + listagens do item na tela.
    if (!(await autoListPart1(name))) return false;

    // B) Preço de referência (primeira linha = mais barato).
    const floor = marketCheapestPrice(name);
    if (floor === null) {
      log('Auto-listagem: ✖ sem preço de referência (nenhuma listagem à venda) — abortando por segurança');
      return false;
    }
    let price = Math.max(1, floor - 1);
    log(`Auto-listagem: mais barato ${fmtGold(floor)} → vamos listar por ${fmtGold(price)}`);

    // C) Vai pra aba My Listings (onde fica o CREATE NEW LISTING).
    for (let t = 0; t < 3 && !byText('p', 'CREATE NEW LISTING'); t++) {
      const tab = byText('p', 'My listings');
      if (tab) { log('Auto-listagem: abrindo My Listings'); click(tab); }
      else log('Auto-listagem: aba "My listings" não encontrada');
      await sleep(800);
    }
    if (!byText('p', 'CREATE NEW LISTING')) { log('Auto-listagem: ✖ My Listings não abriu'); return false; }
    await sleep(500); // deixa as MY LISTINGS renderizarem

    // C2) Se o floor price já é NOSSO, listamos MESMO ASSIM (as unidades novas
    //     do inventário), mas pelo MESMO preço — sem undercutar a própria
    //     oferta. (Nossa listagem aparece no View Market com o BUY desabilitado,
    //     então o "mais barato" lido pode ser a gente mesmo.)
    const mine = myListingPrices(name);
    if (mine.includes(floor)) {
      price = floor;
      log(`Auto-listagem: o floor (${fmtGold(floor)}) já é NOSSO — listando as unidades novas pelo MESMO preço`);
    } else if (mine.length) {
      log(`Auto-listagem: já temos listagem(ns) de "${name}" por ${mine.map(fmtGold).join(', ')} — vamos criar uma nova por ${fmtGold(price)}`);
    }

    // D) Seleciona o item no "Select item" (mesmo popup de busca).
    if (!(await marketPickItem(name))) return false;

    // E) Preenche preço e quantidade (máximo disponível, lido do "(Max. N)").
    const priceInp = document.querySelector('input[placeholder="Price each"]');
    const qtyInp = document.querySelector('input[placeholder="Quantity"]');
    if (!priceInp || !qtyInp) { log('Auto-listagem: ✖ campos Price each / Quantity não encontrados'); return false; }
    const max = listingMaxQty();
    if (!max) { log('Auto-listagem: ✖ "(Max. N)" zerado ou ausente — o item foi mesmo selecionado?'); return false; }
    setNativeInput(priceInp, String(price));
    await sleep(250);
    setNativeInput(qtyInp, String(max));
    await sleep(400);
    log(`Auto-listagem: preenchido — ${fmtGold(price)} cada × ${max} unidade(s). Confirmando...`);

    // F) CREATE LISTING (compara o nº de listagens antes/depois pra confirmar).
    const before = marketListingRows(name).length;
    const btn = byText('h5', 'CREATE LISTING');
    if (!btn) { log('Auto-listagem: ✖ botão CREATE LISTING não encontrado'); return false; }
    click(btn);

    // G) Confirmação: uma linha NOVA com o item em MY LISTINGS.
    for (let t = 0; t < 8; t++) {
      await sleep(700);
      if (marketListingRows(name).length > before) {
        log(`Auto-listagem: ✔ "${name}" listado por ${fmtGold(price)} cada (${max}x)`);
        notify(`🏷 Auto Listagem: "${name}" listado por ${fmtGold(price)} cada (${max}x) — agora é o mais barato!`);
        return true;
      }
    }
    log('Auto-listagem: ⚠ cliquei em CREATE LISTING mas não vi a listagem nova — confira manualmente');
    return false;
  }

  // Item presente no inventário? (fora da nossa UI; o Market está fechado
  // quando isso roda, então os slots visíveis são inventário/equipamento.)
  function itemInInventory(name) {
    const want = String(name || '').trim().toLowerCase();
    if (!want) return false;
    return Array.from(document.querySelectorAll('.stonegy-item-holder-slot span[aria-label]')).some(
      (s) => (s.getAttribute('aria-label') || '').trim().toLowerCase() === want &&
             !s.closest('#stonegy-auto-hunt') && !s.closest('#sah-protect-section') && visible(s)
    );
  }

  let autoDepotBusy = false;
  let stonegyWebpackRequire = null;

  // Obtém o runtime já carregado pelo Next/Webpack sem importar nem substituir
  // módulos do jogo. Isso permite ativar o mesmo estado que a janela do Depot
  // usa; o clique seguinte no inventário é quem envia `depot_move_item` pelo
  // WebSocket nativo, já com o inventoryId correto mantido pelo React.
  function getStonegyWebpackRequire() {
    if (stonegyWebpackRequire) return stonegyWebpackRequire;
    const chunks = window.webpackChunk_N_E;
    if (!chunks || typeof chunks.push !== 'function') return null;
    try {
      const chunkId = 910000000 + Math.floor(Math.random() * 89999999);
      chunks.push([[chunkId], {}, (req) => { stonegyWebpackRequire = req; }]);
    } catch (_) {}
    return stonegyWebpackRequire;
  }

  function setStonegyDepotBox(boxIndex) {
    try {
      const req = getStonegyWebpackRequire();
      const depotState = req && req(49759);
      if (!depotState || typeof depotState.zB !== 'function') return false;
      depotState.zB(boxIndex);
      return true;
    } catch (_) {
      return false;
    }
  }

  function clearStonegyDepotBox() {
    try {
      const req = getStonegyWebpackRequire();
      const depotState = req && req(49759);
      if (depotState && typeof depotState.sG === 'function') depotState.sG();
    } catch (_) {}
  }

  function depotPickerCandidateCells(root) {
    if (!root) return [];
    const cells = Array.from(root.querySelectorAll('button,[role="button"],div')).filter((el) => {
      if (!visible(el)) return false;
      const r = el.getBoundingClientRect();
      if (r.width < 28 || r.width > 90 || r.height < 28 || r.height > 90) return false;
      if (Math.abs(r.width - r.height) > 18) return false;
      return getComputedStyle(el).cursor === 'pointer' && !!el.querySelector('img,svg,span');
    });
    const unique = [];
    const seen = new Set();
    cells.forEach((el) => {
      const r = el.getBoundingClientRect();
      const key = `${Math.round(r.left)}:${Math.round(r.top)}`;
      if (!seen.has(key)) { seen.add(key); unique.push(el); }
    });
    return unique;
  }

  function depotPickerRoot() {
    const title = Array.from(document.querySelectorAll('h3,h4,h5,p,span,div')).find((el) => {
      if (!visible(el) || (el.children && el.children.length > 2)) return false;
      return /^depot chests$/i.test((el.textContent || '').replace(/\s+/g, ' ').trim());
    });
    if (!title) return null;
    for (let n = title.parentElement, i = 0; n && n !== document.body && i < 12; n = n.parentElement, i++) {
      const slots = Array.from(n.querySelectorAll('.stonegy-item-holder-slot')).filter(visible);
      if (slots.length >= 20) return n;
      // O seletor do jogo pode mudar a classe dos quadrados. Aceitamos o
      // menor ancestral que contenha os 20 botões, sem ampliar até a página
      // inteira (o que poderia confundir outros slots da interface com baús).
      if (depotPickerCandidateCells(n).length >= 20) return n;
    }
    return null;
  }

  function depotPickerCells(root) {
    if (!root) return [];
    let cells = Array.from(root.querySelectorAll('.stonegy-item-holder-slot')).filter(visible);
    if (cells.length < 20) cells = depotPickerCandidateCells(root);
    const unique = [];
    const seen = new Set();
    cells.forEach((el) => {
      const r = el.getBoundingClientRect();
      const key = `${Math.round(r.left)}:${Math.round(r.top)}`;
      if (!seen.has(key)) { seen.add(key); unique.push(el); }
    });
    return unique.sort((a, b) => {
      const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect();
      return Math.abs(ra.top - rb.top) > 8 ? ra.top - rb.top : ra.left - rb.left;
    }).slice(0, 20);
  }

  function clickDepotCanvasPosition() {
    const pos = cfg.autoDepotClick;
    const canvas = document.querySelector('canvas');
    if (!pos || !canvas || !visible(canvas)) return false;
    const r = canvas.getBoundingClientRect();
    const opts = {
      bubbles: true, cancelable: true, view: window,
      clientX: r.left + r.width * Math.max(0, Math.min(1, Number(pos.x) || 0)),
      clientY: r.top + r.height * Math.max(0, Math.min(1, Number(pos.y) || 0)),
    };
    canvas.dispatchEvent(new PointerEvent('pointerdown', opts));
    canvas.dispatchEvent(new MouseEvent('mousedown', opts));
    canvas.dispatchEvent(new PointerEvent('pointerup', opts));
    canvas.dispatchEvent(new MouseEvent('mouseup', opts));
    canvas.dispatchEvent(new MouseEvent('click', opts));
    return true;
  }

  function depotInventorySlots(name) {
    const root = document.querySelector('[data-guide="character-inventory"]');
    if (!root) return [];
    const want = String(name || '').trim().toLowerCase();
    return Array.from(root.querySelectorAll('.stonegy-item-holder-slot')).filter((slot) => {
      const span = slot.querySelector('span[aria-label]');
      return visible(slot) && span && (span.getAttribute('aria-label') || '').trim().toLowerCase() === want;
    });
  }

  async function autoDepotFlowImpl(manual) {
    const items = (cfg.autoDepotItems || []).filter(itemInInventory);
    if (!items.length) {
      log('Auto Depot: nenhum item marcado no inventário');
      if (manual) notify('Auto Depot: nenhum item marcado está no inventário.');
      return { ok: true, moved: 0, failed: 0 };
    }
    const box = Math.min(20, Math.max(1, parseInt(cfg.autoDepotBox, 10) || 1));
    let activatedDirectly = setStonegyDepotBox(box - 1);
    let openedPicker = false;

    // Compatibilidade caso o módulo interno mude numa atualização do jogo:
    // abre o móvel salvo e seleciona o baú pela interface. A janela permanece
    // aberta após a seleção — isso é o comportamento normal do Stonegy.
    if (!activatedDirectly) {
      let picker = depotPickerRoot();
      if (!picker && cfg.autoDepotClick) {
        openedPicker = clickDepotCanvasPosition();
        for (let t = 0; t < 14 && !picker; t++) {
          await sleep(300);
          picker = depotPickerRoot();
        }
      }
      if (!picker) {
        notify('Auto Depot: canal direto indisponível e não consegui abrir “DEPOT CHESTS”.');
        return { ok: false, moved: 0, failed: items.length, error: 'depot indisponível' };
      }
      const cells = depotPickerCells(picker);
      if (cells.length < box) {
        notify(`Auto Depot: não encontrei o Depot ${box} na janela.`);
        return { ok: false, moved: 0, failed: items.length, error: 'baú não encontrado' };
      }
      log(`Auto Depot: selecionando Depot ${box} pela janela`);
      click(cells[box - 1]);
      await sleep(450); // o seletor continua aberto; apenas o estado ativo muda
    } else {
      log(`Auto Depot: Depot ${box} ativado pelo canal interno do jogo`);
      await sleep(120); // permite que o hook do inventário receba o novo estado
    }

    let moved = 0;
    let failed = 0;
    for (const name of items) {
      let guard = 0;
      while (guard++ < 60) {
        const before = depotInventorySlots(name);
        if (!before.length) break;
        const slot = before[0];
        click(slot);
        let decreased = false;
        for (let t = 0; t < 10; t++) {
          await sleep(180);
          if (!document.contains(slot) || depotInventorySlots(name).length < before.length) {
            decreased = true; moved++; break;
          }
        }
        if (!decreased) {
          failed++;
          log(`Auto Depot: ⚠ "${name}" não saiu do inventário`);
          break;
        }
      }
    }
    clearStonegyDepotBox();
    if (openedPicker) {
      document.dispatchEvent(new KeyboardEvent('keydown', {
        key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true,
      }));
    }
    log(`Auto Depot: finalizado — ${moved} pilha(s) guardada(s), ${failed} falha(s)`);
    notify(`📦 Auto Depot: ${moved} pilha(s) guardada(s) no Depot ${box}${failed ? ` · ${failed} falha(s)` : ''}`);
    return { ok: failed === 0, moved, failed };
  }

  function runAutoDepotFlow(manual) {
    if (autoDepotBusy) return;
    autoDepotBusy = true;
    if (!manual) bot.autoDepotDone = false;
    autoDepotFlowImpl(!!manual)
      .catch((e) => log('Auto Depot: erro — ' + (e && e.message ? e.message : e)))
      .finally(() => {
        clearStonegyDepotBox();
        autoDepotBusy = false;
        if (!manual) bot.autoDepotDone = true;
      });
  }

  // Fecha o modal do Market (o X do canto), pra liberar a HUD e o bot seguir.
  function closeMarketWindow() {
    const h = byText('h4', 'MARKET');
    if (!h) return;
    let node = h;
    for (let i = 0; i < 14 && node; i++, node = node.parentElement) {
      const x = node.querySelector && node.querySelector('svg[viewBox="0 0 14 14"]');
      if (x) { click(x); return; }
    }
  }

  // FLUXO AUTOMÁTICO (fase AUTO_LIST): lista cada item marcado (ícone do
  // market amarelo na lista de protegidos) que estiver no inventário, um por
  // um, e fecha o Market no fim — mesmo se algo falhar no meio.
  async function autoListFlowImpl() {
    const items = (cfg.autoListItems || []).filter(itemInInventory);
    if (!items.length) { log('Auto-listagem: nenhum item marcado no inventário — nada a listar'); return; }
    log(`Auto-listagem: ${items.length} item(ns) para listar — ${items.join(', ')}`);
    for (const name of items) {
      const ok = await autoListPart2(name);
      if (!ok) log(`Auto-listagem: ⚠ "${name}" não foi listado (veja o motivo acima) — seguindo pro próximo`);
      await sleep(600);
    }
  }

  function runAutoListFlow() {
    if (autoListBusy) return;
    autoListBusy = true;
    bot.autoListDone = false;
    autoListFlowImpl()
      .catch((e) => log('Auto-listagem: erro — ' + (e && e.message ? e.message : e)))
      .finally(async () => {
        closeMarketWindow();
        await sleep(500);
        autoListBusy = false;
        bot.autoListDone = true; // a fase AUTO_LIST vê isso e segue pra hunt
      });
  }

  // Monta o payload (embed) do Discord.
  function buildLootPayload(data) {
    const lines = [];
    if (data.members.length) {
      lines.push('**Balances**');
      data.members.forEach((m) => lines.push(`• ${m.name}: ${m.balance}`));
    }
    if (data.transfers.length) {
      if (lines.length) lines.push('');
      lines.push('**Pagamentos — o líder deve transferir:**');
      data.transfers.forEach((t) => lines.push(`• ${t}`));
    }
    const desc = lines.join('\n').slice(0, 4000) || 'Sem dados de splitter.';
    const fields = data.profitPerMember
      ? [{ name: 'Profit por membro', value: String(data.profitPerMember), inline: false }]
      : [];
    return {
      username: 'STONER — Loot Splitter',
      embeds: [{
        title: '💰 Loot Splitter — snapshot',
        description: desc,
        color: 0xc89b3c,
        fields,
        footer: { text: 'STONER • backup automático do Loot Splitter' },
        timestamp: new Date().toISOString(),
      }],
    };
  }

  // Envia o payload ao Discord através do nosso Worker.
  async function sendLootWebhook(payload) {
    // Offline: usa o background da extensão como proxy (sem servidor remoto).
    // Mantém compatibilidade se __STONER_API__ existir.
    const api = (typeof globalThis !== 'undefined' && globalThis.__STONER_API__) || '';
    if (api) {
      try {
        const ctrl = new AbortController();
        const to = setTimeout(() => ctrl.abort(), 8000);
        const r = await fetch(api + '/loot-webhook', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ webhook: cfg.lootWebhook, payload }),
          signal: ctrl.signal,
        });
        clearTimeout(to);
        return await r.json().catch(() => ({ ok: false }));
      } catch (_) {
        return { ok: false, error: 'falha de rede' };
      }
    }
    // Fallback offline via relay → background
    if (!cfg.lootWebhook) return { ok: false, error: 'webhook vazio' };
    return new Promise((resolve) => {
      const id = 'loot-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
      const onMsg = (ev) => {
        if (ev.source !== window || !ev.data || ev.data.src !== 'cap-relay') return;
        if (ev.data.id !== id) return;
        window.removeEventListener('message', onMsg);
        resolve(ev.data.ok ? { ok: true } : { ok: false, error: (ev.data.data && ev.data.data.erro) || 'falha' });
      };
      window.addEventListener('message', onMsg);
      window.postMessage({
        src: 'cap-page',
        id,
        tipo: 'discordWebhook',
        payload: { webhook: cfg.lootWebhook, payload },
      }, '*');
      setTimeout(() => {
        window.removeEventListener('message', onMsg);
        resolve({ ok: false, error: 'timeout' });
      }, 10000);
    });
  }

  // Texto do motivo de saída (usado no aviso do Discord).
  function reasonText(reason) {
    if (reason === 'gold') return `Gold abaixo do limite (< ${fmtGold(cfg.goldMin)})`;
    if (reason === 'stamina') return `Stamina baixa (< ${fmtStamina(cfg.staminaMin)})`;
    return 'gatilho automático';
  }

  // Payload do backup FINAL (enviado antes de sair da party por um gatilho):
  // um aviso destacado de que o bot saiu sozinho + o último snapshot do splitter.
  function buildExitPayload(data, reason) {
    const base = data
      ? buildLootPayload(data)
      : {
          username: 'STONER — Loot Splitter',
          embeds: [{
            title: '💰 Loot Splitter',
            description: '_(não consegui ler os valores do splitter no momento da saída)_',
            color: 0xc89b3c,
            timestamp: new Date().toISOString(),
          }],
        };
    base.content =
      `🚪 **Saí da party automaticamente** — motivo: **${reasonText(reason)}**.\n` +
      'Segue o último snapshot do Loot Splitter (guarde os valores antes que o splitter zere):';
    base.embeds[0].color = 0xd9822b; // laranja de alerta
    base.embeds[0].title = '🚪 Saída automática — Loot Splitter (backup final)';
    return base;
  }

  // Backup final antes de sair da party. A janela Friends já está aberta (fase
  // EXIT_PARTY); abre o splitter se preciso, lê, envia SEMPRE (com o motivo) e
  // fecha o modal. Não fecha o Friends (a fase ainda vai clicar "Sair da Party").
  async function lootSnapshotBeforeLeave(reason) {
    lootBusy = true;
    let openedModal = false;
    try {
      let data = readLootSplitter();
      if (!data) {
        const btn = find.lootSplitterButton();
        if (btn) { click(btn); openedModal = true; await sleep(900); }
        data = readLootSplitter();
      }
      const res = await sendLootWebhook(buildExitPayload(data, reason));
      if (res && res.ok) log('Backup final do Loot Splitter enviado ao Discord (saída automática) ✔');
      else log('Falha ao enviar o backup final do Loot Splitter');
    } catch (_) {
    } finally {
      if (openedModal) { const f = lootCloseBtn(); if (f) { click(f); await sleep(250); } }
      lootBusy = false;
    }
  }

  // Envia se mudou desde o último envio (ou se forçado, ex.: botão Testar).
  async function maybeSendLoot(data, force) {
    const hash = JSON.stringify({
      p: data.profitPerMember, m: data.members, t: data.transfers,
    });
    if (!force && hash === lastLootHash) return;
    const res = await sendLootWebhook(buildLootPayload(data));
    if (res && res.ok) {
      lastLootHash = hash;
      log('Loot Splitter enviado ao Discord ✔');
      if (force) microToast('✅ Loot Splitter enviado ao Discord', true);
    } else {
      log('Falha ao enviar Loot Splitter ao Discord');
      if (force) notify('Não consegui enviar ao Discord. Confira se o webhook está correto (copie a URL completa do webhook no Discord).');
    }
  }

  // Fecha a janela Friends pelo PRÓPRIO botão (o mesmo ícone que a abre —
  // toggle). O "clique fora" não fechava de forma confiável. Throttle de ~2,5s
  // para não piscar (o fechamento é assíncrono no React; sem o throttle, clicar
  // a cada tick reabriria).
  let friendsCloseAt = 0;
  function closeFriendsWindow() {
    if (!find.friendsWindow()) { friendsCloseAt = 0; return; }
    const now = Date.now();
    if (now - friendsCloseAt < 2500) return;
    friendsCloseAt = now;
    const fb = find.friendsButton();
    if (fb) click(fb);
  }

  // Snapshot proativo: abre o modal (se preciso), lê, envia e fecha o que abriu.
  // manual=true (botão Testar) dá feedback nas pré-condições. force=true envia
  // SEMPRE (ignora o dedupe) — usado no manual e no periódico de 15 min. O
  // dedupe fica só para a captura passiva (quando o usuário abre o modal).
  async function lootSnapshot(manual = false, force = manual) {
    if (lootBusy) return;
    // Este snapshot ABRE a janela Friends e o modal Loot Splitter DO JOGO por
    // ~2s pra ler os valores. Com o bot PARADO, quem está jogando na mão via
    // janelas abrindo sozinhas do nada — intrusivo e estranho. Então o
    // automático só roda com o bot ligado (aí abrir janelas já é esperado).
    // Não afeta: o envio manual (botão do painel) nem a captura PASSIVA
    // (lootPassiveCheck), que só lê quando o próprio usuário abre o modal.
    if (!manual && !bot.running) return;
    if (!cfg.lootWebhook) { if (manual) notify('Cole o webhook do Discord primeiro.'); return; }
    if (!manual && !cfg.lootBackup) return;
    if (cfg.mode !== 'party') {
      if (manual) notify('O Loot Splitter só existe numa party. Selecione modo Party (líder ou membro) e esteja em uma party ativa.');
      return;
    }
    lootBusy = true;
    let openedFriends = false, openedModal = false;
    try {
      let data = readLootSplitter();
      if (!data) {
        if (!find.friendsWindow()) {
          const fb = find.friendsButton();
          if (fb) { click(fb); openedFriends = true; await sleep(700); }
        }
        const btn = find.lootSplitterButton();
        if (btn) { click(btn); openedModal = true; await sleep(900); }
        data = readLootSplitter();
      }
      if (data) {
        await maybeSendLoot(data, force);
      } else if (manual) {
        notify('Não consegui abrir/ler o Loot Splitter. Confirme que você é líder de uma party ativa.');
      }
    } catch (_) {
    } finally {
      if (openedModal) { const f = lootCloseBtn(); if (f) { click(f); await sleep(250); } }
      if (openedFriends) closeFriendsWindow();
      lootBusy = false;
    }
  }

  // Passivo: se o modal já está aberto (usuário abriu), lê e envia na mudança —
  // sem abrir/fechar nada.
  async function lootPassiveCheck() {
    if (lootBusy || !cfg.lootBackup || !cfg.lootWebhook || cfg.mode !== 'party') return;
    const data = readLootSplitter();
    if (data) await maybeSendLoot(data, false);
  }

  // Timers do backup do Loot Splitter — montados só UMA vez (evita duplicar
  // envios se o painel for recriado). Periódico a cada 15 min SEMPRE envia
  // (force), independente de mudança; um primeiro envio ~1,5 min após carregar
  // deixa você verificar sem esperar 15 min; e a captura passiva (modal aberto)
  // a cada 8s envia só na mudança.
  let lootTimersStarted = false;
  function startLootTimers() {
    if (lootTimersStarted) return;
    lootTimersStarted = true;
    setInterval(() => { lootSnapshot(false, true); }, 15 * 60 * 1000);
    setInterval(() => { lootPassiveCheck(); }, 8000);
    setTimeout(() => { lootSnapshot(false, true); }, 90 * 1000);
  }

  // Ao fechar/recarregar a aba, solta a trava de aba NA HORA (só se for nossa),
  // pra outra aba poder assumir sem esperar os 6s de expiração. No F5, o próprio
  // sessionStorage mantém o TAB_ID, então a aba recarregada reconhece/repega a
  // trava normalmente no auto-resume.
  try { addEventListener('pagehide', releaseTabLock); } catch (_) {}

  // O jogo é um SPA — espera o body existir e injeta o painel
  const boot = setInterval(() => {
    if (document.body && !document.getElementById('stonegy-auto-hunt')) {
      clearInterval(boot);
      buildPanel();
      initTabLockChannel(); // canal da trava de aba (antes de um possível auto-resume)
      log('Painel carregado. Configure e clique INICIAR.');
      // Se o bot estava rodando antes do reload (ex.: tela de inatividade),
      // retoma automaticamente — o tick já clica em Retomar se ela aparecer.
      // (A trava de aba no start() garante que só UMA aba retoma de fato.)
      if (lsGet(RUNNING_KEY) === '1') {
        log('Bot estava ativo antes do reload — retomando automaticamente');
        start();
      }
    }
  }, 1000);



  // =====================================================================
  // HUNT METRICS HISTORY (v1.3.2) — XP/h, gold/h por hunt · SOLO vs PARTY
  // Captura ao sair da hunt; mostra no dropdown de hunts recentes.
  // =====================================================================
  const HUNT_METRICS_MAX_RUNS = 8;

  function parseBrNumber(s) {
    if (s == null) return null;
    const t = String(s).trim();
    if (!t) return null;
    // 3.873.986 ou 3,873,986 ou 3873986
    const cleaned = t.replace(/\s/g, '').replace(/\./g, '').replace(/,/g, '');
    const n = parseInt(cleaned, 10);
    return Number.isFinite(n) ? n : null;
  }

  function parseDurationToSec(s) {
    // 00:06:40 ou 11:06:44 ou 1h 21m
    const t = String(s || '').trim();
    let m = t.match(/^(\d+):(\d{2}):(\d{2})$/);
    if (m) return (+m[1]) * 3600 + (+m[2]) * 60 + (+m[3]);
    m = t.match(/^(\d+):(\d{2})$/);
    if (m) return (+m[1]) * 60 + (+m[2]);
    m = t.match(/(\d+)\s*h(?:ours?)?\s*(\d+)\s*m/i);
    if (m) return (+m[1]) * 3600 + (+m[2]) * 60;
    return null;
  }

  function scrapeHuntMetricsFromDom() {
    const out = {
      durationSec: null,
      xp: null, xpH: null,
      rawXp: null, rawXpH: null,
      balance: null, balanceH: null,
      lootTotal: null,
      kills: null,
    };
    try {
      const body = (document.body && document.body.innerText) || '';
      // Jogo usa (1.937.281h) — sem barra; às vezes (1.937.281/h)
      const rateRe = '\\(([+\\-]?[\\d.\\s]+)\\/?h\\)';

      let m = body.match(/Hunt\s*Time[:\s]+(\d{1,2}:\d{2}:\d{2}|\d{1,2}:\d{2})/i);
      if (m) out.durationSec = parseDurationToSec(m[1]);

      m = body.match(new RegExp('Raw\\s*XP[:\\s]+([\\d.\\s]+)\\s*' + rateRe, 'i'));
      if (m) { out.rawXp = parseBrNumber(m[1]); out.rawXpH = parseBrNumber(m[2]); }

      // XP (não Raw): procura linhas "XP:" 
      const xpMatches = [];
      const xpRe = new RegExp('(?:^|\\n)\\s*(Raw\\s*)?XP[:\\s]+([\\d.\\s]+)\\s*' + rateRe, 'gi');
      let xm;
      while ((xm = xpRe.exec(body)) !== null) {
        xpMatches.push({ raw: !!xm[1], total: parseBrNumber(xm[2]), rate: parseBrNumber(xm[3]) });
      }
      for (const row of xpMatches) {
        if (row.raw) {
          if (out.rawXp == null) out.rawXp = row.total;
          if (out.rawXpH == null) out.rawXpH = row.rate;
        } else {
          if (out.xp == null) out.xp = row.total;
          if (out.xpH == null) out.xpH = row.rate;
        }
      }

      m = body.match(new RegExp('Balance[:\\s]+([+\\-]?[\\d.\\s]+)\\s*' + rateRe, 'i'));
      if (m) { out.balance = parseBrNumber(m[1]); out.balanceH = parseBrNumber(m[2]); }

      m = body.match(/Loot\s*Total[:\s]+([\d.\s]+)/i);
      if (m) out.lootTotal = parseBrNumber(m[1]);

      m = body.match(/Kills[:\s]+([\d.\s]+)/i);
      if (m) out.kills = parseBrNumber(m[1]);
    } catch (_) {}
    return out;
  }

  function metricsModeKey() {
    // SOLO vs PARTY (agrupa 2–4 na v1)
    if (cfg.mode === 'party') return 'party';
    return 'solo';
  }

  function metricsStorageKey(huntName, mode) {
    return normalizeHuntKey(huntName) + '|' + (mode || metricsModeKey());
  }

  function fmtRate(n) {
    if (n == null || !Number.isFinite(n)) return '—';
    const abs = Math.abs(Math.round(n));
    let s;
    if (abs >= 1e6) s = (abs / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
    else if (abs >= 1e3) s = (abs / 1e3).toFixed(1).replace(/\.0$/, '') + 'k';
    else s = String(abs);
    return (n < 0 ? '-' : '') + s;
  }

  function fmtDurShort(sec) {
    if (sec == null || !Number.isFinite(sec) || sec <= 0) return '—';
    const m = Math.round(sec / 60);
    if (m < 60) return m + ' min';
    const h = Math.floor(m / 60);
    const mm = m % 60;
    return h + 'h' + (mm ? mm + 'm' : '');
  }

  function primaryXpRateOf(run) {
    if (!run || typeof run !== 'object') return null;
    if (run.rawXpH != null && Number.isFinite(run.rawXpH)) return run.rawXpH;
    if (run.xpH != null && Number.isFinite(run.xpH)) return run.xpH;
    return null;
  }

  function primaryXpLabelOf(run) {
    if (!run || typeof run !== 'object') return '';
    if (run.rawXpH != null && Number.isFinite(run.rawXpH)) return 'Raw XP/h';
    if (run.xpH != null && Number.isFinite(run.xpH)) return 'XP/h';
    return '';
  }

  function averageRuns(runs) {
    if (!runs || !runs.length) return null;
    const keys = ['durationSec', 'xp', 'xpH', 'rawXp', 'rawXpH', 'balance', 'balanceH', 'lootTotal', 'kills'];
    const avg = {};
    for (const k of keys) {
      const vals = runs.map((r) => r[k]).filter((v) => typeof v === 'number' && Number.isFinite(v));
      avg[k] = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
    }
    const weightedRate = (totalKey, rateKey) => {
      const totalRuns = runs.filter((r) =>
        typeof r[totalKey] === 'number' && Number.isFinite(r[totalKey]) &&
        typeof r.durationSec === 'number' && Number.isFinite(r.durationSec) &&
        r.durationSec > 0
      );
      if (totalRuns.length) {
        const total = totalRuns.reduce((sum, r) => sum + r[totalKey], 0);
        const sec = totalRuns.reduce((sum, r) => sum + r.durationSec, 0);
        return sec > 0 ? total * 3600 / sec : null;
      }

      const rateRuns = runs.filter((r) =>
        typeof r[rateKey] === 'number' && Number.isFinite(r[rateKey]) &&
        typeof r.durationSec === 'number' && Number.isFinite(r.durationSec) &&
        r.durationSec > 0
      );
      if (rateRuns.length) {
        const sec = rateRuns.reduce((sum, r) => sum + r.durationSec, 0);
        return sec > 0
          ? rateRuns.reduce((sum, r) => sum + r[rateKey] * r.durationSec, 0) / sec
          : null;
      }
      return avg[rateKey];
    };
    avg.xpH = weightedRate('xp', 'xpH');
    avg.rawXpH = weightedRate('rawXp', 'rawXpH');
    avg.balanceH = weightedRate('balance', 'balanceH');
    avg.n = runs.length;
    return avg;
  }

  function getMetricsEntry(huntName, mode) {
    if (!cfg.huntMetrics) cfg.huntMetrics = {};
    const key = metricsStorageKey(huntName, mode);
    return cfg.huntMetrics[key] || null;
  }

  function recordHuntMetricsSnapshot(reason) {
    try {
      const hunt = detectCurrentHuntName() || cfg.huntName || '';
      if (!hunt) return false;
      const scraped = scrapeHuntMetricsFromDom();
      // precisa de pelo menos xp/h ou balance/h ou tempo
      if (scraped.xpH == null && scraped.rawXpH == null && scraped.balanceH == null && scraped.durationSec == null) {
        return false;
      }
      // evita gravar hunt de 0 segundos / vazia
      if (scraped.durationSec != null && scraped.durationSec < 30) return false;

      const mode = metricsModeKey();
      if (!cfg.huntMetrics) cfg.huntMetrics = {};
      const key = metricsStorageKey(hunt, mode);
      const entry = cfg.huntMetrics[key] || {
        huntName: hunt,
        mode: mode,
        runs: [],
      };
      entry.huntName = hunt;
      entry.mode = mode;
      const run = {
        at: Date.now(),
        reason: reason || 'exit',
        durationSec: scraped.durationSec,
        xp: scraped.xp,
        xpH: scraped.xpH,
        rawXp: scraped.rawXp,
        rawXpH: scraped.rawXpH,
        balance: scraped.balance,
        balanceH: scraped.balanceH,
        lootTotal: scraped.lootTotal,
        kills: scraped.kills,
      };
      // dedup / upgrade: se última run recente só tem tempo, substitui com dados completos
      const last = entry.runs[0];
      if (last && (Date.now() - (last.at || 0)) < 180000) {
        const lastPoor = primaryXpRateOf(last) == null && last.balanceH == null;
        const runRich = primaryXpRateOf(run) != null || run.balanceH != null;
        const closeDuration =
          typeof last.durationSec === 'number' && Number.isFinite(last.durationSec) &&
          typeof run.durationSec === 'number' && Number.isFinite(run.durationSec) &&
          Math.abs(last.durationSec - run.durationSec) <= 120;
        const sameRecentExit = closeDuration && (
          last.reason === 'exit_leave' ||
          last.reason === 'leaving' ||
          last.reason === 'left' ||
          run.reason === 'exit_leave' ||
          run.reason === 'leaving' ||
          run.reason === 'left'
        );
        if (lastPoor && runRich) {
          entry.runs[0] = run;
          entry.avg = averageRuns(entry.runs);
          cfg.huntMetrics[key] = entry;
          saveConfig();
          log(
            'Métricas atualizadas [' + mode.toUpperCase() + '] "' + hunt + '": ' +
            primaryXpLabelOf(run) + ' ' + fmtRate(primaryXpRateOf(run)) +
            ' · Gold/h ' + fmtRate(run.balanceH) +
            ' · ' + fmtDurShort(run.durationSec)
          );
          try { updateHuntMetricsUI(); } catch (_) {}
          return true;
        }
        if (sameRecentExit) {
          entry.runs[0] = run;
          entry.avg = averageRuns(entry.runs);
          cfg.huntMetrics[key] = entry;
          saveConfig();
          try { updateHuntMetricsUI(); } catch (_) {}
          return true;
        }
        const sameXp = primaryXpRateOf(last) === primaryXpRateOf(run) && last.balanceH === run.balanceH;
        if (sameXp) return false;
      }
      entry.runs.unshift(run);
      if (entry.runs.length > HUNT_METRICS_MAX_RUNS) entry.runs.length = HUNT_METRICS_MAX_RUNS;
      entry.avg = averageRuns(entry.runs);
      cfg.huntMetrics[key] = entry;
      saveConfig();
      log(
        'Métricas salvas [' + mode.toUpperCase() + '] "' + hunt + '": ' +
        primaryXpLabelOf(run) + ' ' + fmtRate(primaryXpRateOf(run)) +
        ' · Gold/h ' + fmtRate(run.balanceH) +
        ' · ' + fmtDurShort(run.durationSec)
      );
      try { updateHuntMetricsUI(); } catch (_) {}
      return true;
    } catch (e) {
      try { log('Métricas: falha ao salvar — ' + (e && e.message)); } catch (_) {}
      return false;
    }
  }

  function metricsLineFor(huntName, mode) {
    const entry = getMetricsEntry(huntName, mode);
    if (!entry || !entry.runs || !entry.runs.length) return '';
    const latest = entry.runs[0];
    const avg = entry.avg || averageRuns(entry.runs);
    const a = latest;
    const parts = [];
    if (primaryXpRateOf(a) != null) parts.push(fmtRate(primaryXpRateOf(a)) + ' ' + primaryXpLabelOf(a));
    if (a.balanceH != null) parts.push(fmtRate(a.balanceH) + ' gold/h');
    if (a.durationSec != null) parts.push('~' + fmtDurShort(a.durationSec));
    if (!parts.length) return '';
    let line = parts.join(' - ');
    if (avg && avg.n > 1) {
      const avgParts = [];
      if (primaryXpRateOf(avg) != null) avgParts.push(fmtRate(primaryXpRateOf(avg)) + ' ' + primaryXpLabelOf(avg));
      if (avg.balanceH != null) avgParts.push(fmtRate(avg.balanceH) + ' gold/h');
      if (avgParts.length) line += ' | media ' + avg.n + ': ' + avgParts.join(' - ');
    }
    return line;
    return parts.join(' · ') + (a.n > 1 ? ' (média ' + a.n + ')' : '');
  }

  function updateHuntMetricsUI() {
    if (!ui) return;
    if (ui.huntMetricsBox) {
      const name = (ui.hunt && ui.hunt.value.trim()) || cfg.huntName || detectCurrentHuntName() || '';
      if (!name) {
        ui.huntMetricsBox.innerHTML = '<span class="sah-hm-empty">Sem histórico ainda — saia de uma hunt para gravar</span>';
        return;
      }
      const solo = metricsLineFor(name, 'solo');
      const party = metricsLineFor(name, 'party');
      let html = '<div class="sah-hm-title">' + name + '</div>';
      if (!solo && !party) {
        html += '<div class="sah-hm-empty">Nenhuma métrica salva para esta hunt</div>';
      } else {
        if (solo) html += '<div class="sah-hm-row"><span class="sah-hm-tag solo">SOLO</span> ' + solo + '</div>';
        if (party) html += '<div class="sah-hm-row"><span class="sah-hm-tag party">PARTY</span> ' + party + '</div>';
      }
      ui.huntMetricsBox.innerHTML = html;
    }
  }

  // Captura ao sair da hunt (borda inHunt true → false) e antes do Finalizar
  if (!bot._metricsWatchInstalled) {
    bot._metricsWatchInstalled = true;
    bot._metricsWasInHunt = false;
    bot._metricsCapturedThisStay = false;
    setInterval(() => {
      try {
        const nowIn = (typeof inHunt === 'function') ? inHunt() : false;
        if (nowIn && !bot._metricsWasInHunt) {
          bot._metricsCapturedThisStay = false;
        }
        // pouco antes de sair: se já clicou finalizar / saindo
        if (nowIn && !bot._metricsCapturedThisStay) {
          const leaving = !!(find.saindoDaHunt && find.saindoDaHunt());
          if (leaving) {
            if (recordHuntMetricsSnapshot('leaving')) bot._metricsCapturedThisStay = true;
          }
        }
        // saiu de fato
        if (!nowIn && bot._metricsWasInHunt && !bot._metricsCapturedThisStay) {
          // analyzer pode ter sumido — tenta mesmo assim
          recordHuntMetricsSnapshot('left');
          bot._metricsCapturedThisStay = true;
        }
        // A hunt terminou de fato. Salva as métricas antes e então limpa o
        // Damage Analyzer para a próxima hunt começar do zero.
        if (!nowIn && bot._metricsWasInHunt) {
          try {
            if (typeof daReset === 'function') {
              daReset();
              log('Damage Analyzer resetado ao finalizar a hunt');
            }
          } catch (_) {}
        }
        bot._metricsWasInHunt = nowIn;
      } catch (_) {}
    }, 1000);
  }

  // =====================================================================
  // HUNT PRESETS (v1.3.0) — skills, curas, potions, posição por hunt+classe
  // Salvar = sempre MANUAL. Aplicar = manual ou automático ao entrar na hunt.
  // =====================================================================
  if (!bot.liveBattle) bot.liveBattle = null;
  if (!bot.liveVocation) bot.liveVocation = '';
  if (!bot.liveCharName) bot.liveCharName = '';
  if (!bot.presetAppliedFor) bot.presetAppliedFor = '';

  function capWsSend(type, data) {
    try {
      window.postMessage({
        __capSend: true,
        id: 'preset-' + Date.now() + '-' + Math.random().toString(36).slice(2, 6),
        texto: JSON.stringify({ type: type, data: data || {} }),
      }, '*');
      return true;
    } catch (_) {
      return false;
    }
  }

  function normalizeHuntKey(name) {
    return String(name || '')
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, ' ')
      .trim();
  }

  function normalizeVoc(v) {
    const s = String(v || '').toLowerCase();
    if (/knight|ek\b|elite knight/.test(s)) return 'Knight';
    if (/paladin|rp\b|royal paladin/.test(s)) return 'Paladin';
    if (/sorcerer|ms\b|master sorcerer/.test(s)) return 'Sorcerer';
    if (/druid|ed\b|elder druid/.test(s)) return 'Druid';
    if (/monk/.test(s)) return 'Monk';
    return v ? String(v) : '';
  }

  function detectVocation() {
    if (bot.liveVocation) return normalizeVoc(bot.liveVocation);
    try {
      const body = (document.body && document.body.innerText) || '';
      const m = body.match(/\b(Elite Knight|Knight|Royal Paladin|Paladin|Master Sorcerer|Sorcerer|Elder Druid|Druid|Monk)\b/i);
      if (m) return normalizeVoc(m[1]);
    } catch (_) {}
    return '';
  }

  function detectCurrentHuntName() {
    // 1) nome vindo do WebSocket (mais confiável)
    if (bot._rxHuntName && String(bot._rxHuntName).trim().length >= 3) {
      return String(bot._rxHuntName).replace(/\s+/g, ' ').trim();
    }
    // 2) último nome bom detectado nesta sessão
    if (bot._lastGoodHuntName && String(bot._lastGoodHuntName).trim().length >= 3) {
      return String(bot._lastGoodHuntName).replace(/\s+/g, ' ').trim();
    }
    try {
      const body = (document.body && document.body.innerText) || '';
      // Título logo acima de "Hunt Time" (padrão do painel da hunt)
      // Ex.: "LOWER ROSHAMUUL\n...Hunt Time: 00:06:40" ou "Hell Hub"
      let m = body.match(
        /([A-Za-z][A-Za-z0-9'\-]+(?:[ \t]+[A-Za-z0-9'\-]+){0,5})\s*(?:\r?\n|\s)[^\n]{0,120}?Hunt\s*Time/i
      );
      if (m) {
        let name = m[1].replace(/\s+/g, ' ').trim();
        // descarta labels do analyzer
        if (!/^(Raw\s*XP|XP|Kills|Balance|Loot|Next\s*Level|Monsters|HUNT|RESET|STORE)$/i.test(name)) {
          bot._lastGoodHuntName = name;
          return name;
        }
      }
      // Perto de "Finalizar Hunt" / "Saindo da hunt"
      m = body.match(
        /([A-Za-z][A-Za-z0-9'\-]+(?:[ \t]+[A-Za-z0-9'\-]+){0,5})\s*(?:\r?\n|\s)[^\n]{0,80}?(?:Finalizar\s+Hunt|Saindo\s+da\s+hunt|Hunt\s*Time)/i
      );
      if (m) {
        let name = m[1].replace(/\s+/g, ' ').trim();
        if (!/^(Raw|XP|Kills|Balance|Loot|Next|Monsters|HUNT|RESET|STORE|PARTY|SOLO)$/i.test(name)) {
          bot._lastGoodHuntName = name;
          return name;
        }
      }
    } catch (_) {}
    // 3) nome digitado no painel do bot (usuário escolheu a hunt)
    if (cfg.huntName && String(cfg.huntName).trim().length >= 2) {
      return String(cfg.huntName).replace(/\s+/g, ' ').trim();
    }
    return '';
  }

  function presetStorageKey(hunt, voc) {
    return normalizeHuntKey(hunt) + '|' + normalizeVoc(voc);
  }

  function getLiveBattleSnapshot() {
    const b = bot.liveBattle;
    if (!b || typeof b !== 'object') return null;
    return {
      selectedHeal: b.selectedHeal || '',
      selectedHealPercent: b.selectedHealPercent ?? 50,
      selectedHealSecondary: b.selectedHealSecondary || '',
      selectedHealPercentSecondary: b.selectedHealPercentSecondary ?? 50,
      selectedHealTertiary: b.selectedHealTertiary || '',
      selectedHealPercentTertiary: b.selectedHealPercentTertiary ?? 50,
      selectedHealQuaternary: b.selectedHealQuaternary || '',
      selectedHealPercentQuaternary: b.selectedHealPercentQuaternary ?? 50,
      selectedManaPotion: b.selectedManaPotion || '',
      selectedManaPotionPercent: b.selectedManaPotionPercent ?? 20,
      selectedArrow: b.selectedArrow ?? null,
      selectedSkills: Array.isArray(b.selectedSkills) ? b.selectedSkills.slice() : [],
      selectedSkillsMinCreatures: b.selectedSkillsMinCreatures && typeof b.selectedSkillsMinCreatures === 'object'
        ? { ...b.selectedSkillsMinCreatures } : {},
      selectedSupportSkill: b.selectedSupportSkill ?? null,
      selectedSupportSkills: Array.isArray(b.selectedSupportSkills) ? b.selectedSupportSkills.slice() : [null, null],
    };
  }

  function saveHuntPresetManual() {
    const hunt = detectCurrentHuntName();
    const voc = detectVocation();
    if (!hunt) {
      log('Preset: não consegui identificar a hunt atual (entre numa hunt ou preencha o nome no bot)');
      return false;
    }
    if (!voc) {
      log('Preset: não consegui identificar a classe do personagem');
      return false;
    }
    const battle = getLiveBattleSnapshot();
    if (!battle || !(battle.selectedSkills && battle.selectedSkills.some(Boolean))) {
      // ainda salva se tiver posição; avisa se battle vazio
      log('Preset: battle config ainda não chegou do jogo — abra/altere uma skill ou cura uma vez para o bot capturar');
    }
    if (!cfg.huntPresets || typeof cfg.huntPresets !== 'object') cfg.huntPresets = {};
    const key = presetStorageKey(hunt, voc);
    cfg.huntPresets[key] = {
      huntName: hunt,
      vocation: voc,
      position: cfg.position ? { x: cfg.position.x, y: cfg.position.y } : null,
      battle: battle,
      savedAt: Date.now(),
    };
    saveConfig();
    log('Preset salvo: "' + hunt + '" / ' + voc + (cfg.position ? ' + pos (' + cfg.position.x + ',' + cfg.position.y + ')' : ''));
    updatePresetUI();
    return true;
  }

  function findHuntPreset(hunt, voc) {
    if (!cfg.huntPresets) return null;
    const key = presetStorageKey(hunt, voc);
    if (cfg.huntPresets[key]) return cfg.huntPresets[key];
    // match parcial pelo nome da hunt
    const nk = normalizeHuntKey(hunt);
    const nv = normalizeVoc(voc);
    for (const k of Object.keys(cfg.huntPresets)) {
      const p = cfg.huntPresets[k];
      if (!p) continue;
      if (normalizeVoc(p.vocation) !== nv) continue;
      const pn = normalizeHuntKey(p.huntName || k.split('|')[0]);
      if (pn && (nk.includes(pn) || pn.includes(nk))) return p;
    }
    return null;
  }

  async function applyHuntPreset(opts) {
    opts = opts || {};
    const hunt = opts.hunt || detectCurrentHuntName();
    const voc = opts.voc || detectVocation();
    if (!hunt || !voc) {
      if (!opts.silent) log('Preset: hunt ou classe não identificada');
      return false;
    }
    const preset = findHuntPreset(hunt, voc);
    if (!preset) {
      if (!opts.silent) log('Preset: nenhum salvo para "' + hunt + '" / ' + voc);
      updatePresetUI();
      return false;
    }

    // Posição → cfg do bot (fase POSITION / clique na grade)
    if (preset.position && typeof preset.position.x === 'number') {
      cfg.position = { x: preset.position.x, y: preset.position.y };
      saveConfig();
      if (ui.updateSavedPosDisplay) ui.updateSavedPosDisplay();
      // tenta via WS também
      capWsSend('hunt_change_party_position', { x: preset.position.x, y: preset.position.y });
    }

    const b = preset.battle;
    if (b) {
      // skills
      capWsSend('select_skills', {
        selectedSkills: b.selectedSkills || [],
        selectedSupportSkill: b.selectedSupportSkill ?? null,
        selectedSupportSkills: b.selectedSupportSkills || [null, null],
        selectedSkillsMinCreatures: b.selectedSkillsMinCreatures || {},
      });
      // curas (1..4)
      const heals = [
        [b.selectedHeal, b.selectedHealPercent, 1],
        [b.selectedHealSecondary, b.selectedHealPercentSecondary, 2],
        [b.selectedHealTertiary, b.selectedHealPercentTertiary, 3],
        [b.selectedHealQuaternary, b.selectedHealPercentQuaternary, 4],
      ];
      for (const [name, pct, idx] of heals) {
        if (!name) continue;
        capWsSend('select_heal', {
          selectedHeal: name,
          selectedHealPercent: typeof pct === 'number' ? pct : 50,
          healIdx: idx,
        });
      }
      if (b.selectedManaPotion) {
        capWsSend('select_mana_potion', {
          selectedManaPotion: b.selectedManaPotion,
          selectedManaPotionPercent: b.selectedManaPotionPercent ?? 20,
        });
      }
      if (b.selectedArrow != null) {
        capWsSend('select_arrow', { selectedArrow: b.selectedArrow });
      }
    }

    bot.presetAppliedFor = presetStorageKey(hunt, voc);
    if (!opts.silent) {
      log('Preset aplicado: "' + (preset.huntName || hunt) + '" / ' + voc);
    }
    updatePresetUI();
    return true;
  }

  function maybeAutoApplyHuntPreset(reason) {
    if (!cfg.presetAutoApply) return false;
    const isRunning = !!(bot.running || lsGet(RUNNING_KEY) === '1');
    if (!isRunning) return false;
    // só faz sentido dentro da hunt
    try {
      if (typeof inHunt === 'function' && !inHunt()) return false;
    } catch (_) {}
    const hunt = detectCurrentHuntName();
    const voc = detectVocation();
    if (!hunt || !voc) {
      return false;
    }
    const key = presetStorageKey(hunt, voc);
    if (bot.presetAppliedFor === key) return false;
    const preset = findHuntPreset(hunt, voc);
    if (!preset) {
      // marca tentativa vazia para não spammar log a cada tick
      return false;
    }
    log('Preset auto (' + (reason || 'enter') + '): aplicando "' + (preset.huntName || hunt) + '" / ' + voc);
    applyHuntPreset({ hunt: hunt, voc: voc, silent: true });
    return true;
  }

  // Watcher: detecta ENTRADA na hunt e aplica com atraso (jogo precisa montar)
  if (!bot._presetWatchInstalled) {
    bot._presetWatchInstalled = true;
    bot._presetWasInHunt = false;
    bot._presetEnterAt = 0;
    bot._presetRetryLeft = 0;
    setInterval(() => {
      try {
        if (!cfg.presetAutoApply) {
          bot._presetWasInHunt = (typeof inHunt === 'function') ? inHunt() : false;
          return;
        }
        const nowIn = (typeof inHunt === 'function') ? inHunt() : false;
        if (nowIn && !bot._presetWasInHunt) {
          // acabou de entrar
          bot.presetAppliedFor = '';
          bot._presetEnterAt = Date.now();
          bot._presetRetryLeft = 6;
          log('Preset auto: hunt detectada — aplicando em ~2s…');
        }
        if (!nowIn && bot._presetWasInHunt) {
          // saiu da hunt — libera para próxima
          bot.presetAppliedFor = '';
          bot._presetRetryLeft = 0;
        }
        bot._presetWasInHunt = nowIn;
        if (nowIn && bot._presetRetryLeft > 0) {
          if (Date.now() - bot._presetEnterAt < 1800) return;
          const ok = maybeAutoApplyHuntPreset('watcher');
          if (ok) bot._presetRetryLeft = 0;
          else bot._presetRetryLeft -= 1;
        }
      } catch (_) {}
    }, 1000);
  }

  function onCapRxForPresets(raw) {
    try {
      const msg = typeof raw === 'string' ? JSON.parse(raw) : raw;
      if (!msg || !msg.type) return;
      const t = msg.type;
      const d = msg.data || {};
      if (t === 'update_battle_config') {
        bot.liveBattle = d && typeof d === 'object' ? d : bot.liveBattle;
        updatePresetUI();
      } else if (t === 'session_bootstrap') {
        const ch = d.character || d.player || d;
        if (ch) {
          if (ch.vocation) bot.liveVocation = normalizeVoc(ch.vocation);
          if (ch.name) bot.liveCharName = String(ch.name);
        }
      } else if (t === 'hunt_bootstrap' || t === 'hunt:bootstrap' || t === 'start_hunt' || t === 'hunt:start') {
        const hn = d.huntName || d.hunt_name || d.name || (d.hunt && (d.hunt.name || d.hunt.title));
        if (hn && typeof hn === 'string' && hn.trim().length >= 2) {
          bot._rxHuntName = hn.trim();
          bot._lastGoodHuntName = bot._rxHuntName;
        }
        setTimeout(maybeAutoApplyHuntPreset, 1200);
      } else if (t === 'character:patch' || t === 'update_levelinfo') {
        if (d.vocation) bot.liveVocation = normalizeVoc(d.vocation);
      }
      // captura genérica de nome de hunt em payloads
      if (!bot._rxHuntName && d) {
        const cand = d.huntName || d.hunt_name || d.locationName || d.mapName;
        if (typeof cand === 'string' && cand.trim().length >= 3 && cand.trim().length <= 40) {
          bot._rxHuntName = cand.trim();
          bot._lastGoodHuntName = bot._rxHuntName;
        }
      }
    } catch (_) {}
  }

  // listener único para presets (além do DA)
  if (!bot._presetRxInstalled) {
    bot._presetRxInstalled = true;
    window.addEventListener('message', (ev) => {
      if (ev.source !== window || !ev.data || !ev.data.__cap) return;
      if (ev.data.tipo === 'rx' && typeof ev.data.dado === 'string') {
        onCapRxForPresets(ev.data.dado);
      }
    });
  }

  function updatePresetUI() {
    if (!ui || !ui.presetStatus) return;
    const hunt = detectCurrentHuntName();
    const voc = detectVocation();
    const battleOk = !!(bot.liveBattle && bot.liveBattle.selectedSkills);
    let line = 'Hunt: ' + (hunt || '—') + ' · Classe: ' + (voc || '—');
    if (!battleOk) line += ' · battle: aguardando jogo';
    else line += ' · battle: ok';
    if (hunt && voc) {
      const p = findHuntPreset(hunt, voc);
      line += p ? ' · preset: SALVO' : ' · preset: não salvo';
    }
    ui.presetStatus.textContent = line;
    if (ui.presetAuto) ui.presetAuto.checked = !!cfg.presetAutoApply;
  }

  // =====================================================================
  // DAMAGE ANALYZER (v2.0.0) — parser real 0x1c + combate sem duplicação
  // =====================================================================

  const DA_HOST = 'cap-damage-analyzer';
  const DA_DPS_WINDOW_MS = 1000;

  const DA_ELEMENTS = {
    1: 'Earth',
    2: 'Fire',
    3: 'Ice',
    4: 'Energy',
    5: 'Mana',
    6: 'Holy',
    7: 'Death',
    8: 'Physical',
    9: 'Life Drain',
  };

  function daCreateState() {
    return {
      entities: new Map(),

      startedAt: null,
      updatedAt: null,

      names: new Map(),
      partyIds: new Set(),

      frames: 0,
      parsedFrames: 0,
      confirmedHits: 0,
      invalidFrames: 0,

      ignoredSgFrames: 0,

      skills: new Map(),

      lastOp: null,
      lastErr: null,
      lastLen: 0,
      lastSource: '',
      lastSpellStrings: [],
    };
  }

  const DA_SESSION_KEY = 'cap-da-active-hunt-v1';
  let daPersistTimer = null;

  function daSaveSession() {
    try {
      const elapsedMs = daState.startedAt != null && daState.updatedAt != null ? Math.max(0, daState.updatedAt - daState.startedAt) : 0;
      const data = {
        version: 1, elapsedMs,
        entities: [...daState.entities.values()].map((b) => ({ ...b, dealtWin: [], takenWin: [], dealtEl: [...b.dealtEl.entries()], takenEl: [...b.takenEl.entries()] })),
        names: [...daState.names.entries()], partyIds: [...daState.partyIds],
        skills: [...daState.skills.values()].map((s) => ({ ...s, lastAt: 0, lastCastAt: null })),
        frames: daState.frames, parsedFrames: daState.parsedFrames, confirmedHits: daState.confirmedHits,
        invalidFrames: daState.invalidFrames, ignoredSgFrames: daState.ignoredSgFrames,
        lastOp: daState.lastOp, lastErr: daState.lastErr, lastLen: daState.lastLen,
        lastSource: daState.lastSource, lastSpellStrings: daState.lastSpellStrings,
      };
      sessionStorage.setItem(DA_SESSION_KEY, JSON.stringify(data));
    } catch (_) {}
  }

  function daScheduleSave() {
    if (daPersistTimer) return;
    daPersistTimer = setTimeout(() => { daPersistTimer = null; daSaveSession(); }, 300);
  }

  function daLoadSession() {
    try {
      const raw = sessionStorage.getItem(DA_SESSION_KEY);
      if (!raw) return daCreateState();
      const saved = JSON.parse(raw);
      if (!saved || saved.version !== 1) return daCreateState();
      const state = daCreateState();
      const now = daNow();
      const elapsedMs = Math.max(0, Number(saved.elapsedMs) || 0);
      if (elapsedMs > 0) { state.startedAt = now - elapsedMs; state.updatedAt = now; }
      for (const b of saved.entities || []) {
        if (!daIdOk(b.id)) continue;
        state.entities.set(b.id, { id: b.id, dealtSum: Number(b.dealtSum) || 0, takenSum: Number(b.takenSum) || 0,
          dealtMax: Number(b.dealtMax) || 0, takenMax: Number(b.takenMax) || 0, dealtHits: Number(b.dealtHits) || 0,
          takenHits: Number(b.takenHits) || 0, dealtWin: [], takenWin: [], dealtEl: new Map(b.dealtEl || []), takenEl: new Map(b.takenEl || []) });
      }
      state.names = new Map(saved.names || []);
      state.partyIds = new Set(saved.partyIds || []);
      for (const s of saved.skills || []) {
        if (!s || !s.name) continue;
        state.skills.set(String(s.name), { name: String(s.name), casts: Number(s.casts) || 0, hits: Number(s.hits) || 0,
          damage: Number(s.damage) || 0, lastAt: 0, lastCastAt: null });
      }
      for (const key of ['frames', 'parsedFrames', 'confirmedHits', 'invalidFrames', 'ignoredSgFrames', 'lastOp', 'lastErr', 'lastLen', 'lastSource', 'lastSpellStrings']) if (saved[key] !== undefined) state[key] = saved[key];
      log('Damage Analyzer restaurado após recarregar a página');
      return state;
    } catch (_) { return daCreateState(); }
  }

  let daState = daLoadSession();

  const DA_CAPTURE_MAX_FRAMES = 2000;

  let daCapture = {
    active: false,
    startedAt: null,
    frames: [],
  };

  let daPaintQueued = false;
  let daCollapsed =
    localStorage.getItem('cap-da-collapsed') === '1';

  let daDebug =
    localStorage.getItem('cap-da-debug') === '1';

  function daFmt(n) {
    return Math.round(n || 0)
      .toLocaleString('pt-BR');
  }

  function daNow() {
    return performance.now();
  }

  function daEnsure(id) {
    let b = daState.entities.get(id);

    if (!b) {
      b = {
        id,

        dealtSum: 0,
        takenSum: 0,

        dealtMax: 0,
        takenMax: 0,

        dealtHits: 0,
        takenHits: 0,

        dealtWin: [],
        takenWin: [],

        dealtEl: new Map(),
        takenEl: new Map(),
      };

      daState.entities.set(id, b);
    }

    return b;
  }

  function daEnsureSkill(name) {
    const key =
      String(name || '')
        .trim();

    if (!key) {
      return null;
    }

    let s =
      daState.skills.get(key);

    if (!s) {
      s = {
        name: key,
        casts: 0,
        hits: 0,
        damage: 0,
        lastAt: 0,
        lastCastAt: null,
      };

      daState.skills.set(
        key,
        s
      );
    }

    return s;
  }

  function daPeak(win, amount, at, prevMax) {
    const next =
      win.filter(
        (h) =>
          at - h.at <=
          DA_DPS_WINDOW_MS
      );

    next.push({
      at,
      amount,
    });

    const cur =
      next.reduce(
        (sum, h) =>
          sum + h.amount,
        0
      );

    return {
      win: next,
      max:
        Math.max(
          prevMax,
          cur
        ),
    };
  }

  function daAddEl(
    map,
    el,
    amount
  ) {
    if (el == null) {
      return;
    }

    map.set(
      el,
      (map.get(el) || 0) +
        amount
    );
  }

  function daIdOk(id) {
    return (
      typeof id === 'number' &&
      id > 0 &&
      id < 200
    );
  }

  function daRecord(
    hits,
    source
  ) {
    if (
      !hits ||
      !hits.length
    ) {
      return false;
    }

    const at = daNow();
    let any = false;

    for (const h of hits) {
      if (
        !h ||
        !(h.amount > 0)
      ) {
        continue;
      }

      const id =
        h.runtimePlayerId == null
          ? 0
          : h.runtimePlayerId;

      if (!daIdOk(id)) {
        continue;
      }

      const b =
        daEnsure(id);

      if (h.asDealt) {
        const p =
          daPeak(
            b.dealtWin,
            h.amount,
            at,
            b.dealtMax
          );

        b.dealtSum +=
          h.amount;

        b.dealtHits++;

        b.dealtWin =
          p.win;

        b.dealtMax =
          p.max;

        daAddEl(
          b.dealtEl,
          h.element,
          h.amount
        );

        daState
          .confirmedHits++;

        any = true;
      }

      if (h.asTaken) {
        const p =
          daPeak(
            b.takenWin,
            h.amount,
            at,
            b.takenMax
          );

        b.takenSum +=
          h.amount;

        b.takenHits++;

        b.takenWin =
          p.win;

        b.takenMax =
          p.max;

        daAddEl(
          b.takenEl,
          h.element,
          h.amount
        );

        any = true;
      }
    }

    if (!any) {
      return false;
    }

    if (
      daState.startedAt ==
      null
    ) {
      daState.startedAt =
        at;
    }

    daState.updatedAt =
      at;

    daState.lastSource =
      source || 'parser';

    daScheduleSave();
    daSchedulePaint();

    return true;
  }

  function daDps(sum) {
    if (
      !sum ||
      daState.startedAt ==
        null ||
      daState.updatedAt ==
        null
    ) {
      return 0;
    }

    const sec =
      Math.max(
        (
          daState.updatedAt -
          daState.startedAt
        ) / 1000,
        0.001
      );

    return (
      sum / sec
    );
  }

  function daSkillDps(
    damage
  ) {
    return daDps(
      damage
    );
  }

  function daElChips(
    map,
    total
  ) {
    if (!map.size) {
      return (
        '<span class="da-el empty">—</span>'
      );
    }

    const arr =
      [...map.entries()]
        .map(
          ([el, amount]) => ({
            el,
            amount,
            label:
              DA_ELEMENTS[
                el
              ] ||
              ('E' + el),
            pct:
              total > 0
                ? Math.round(
                    (
                      amount /
                      total
                    ) * 100
                  )
                : 0,
          })
        )
        .sort(
          (a, b) =>
            b.amount -
            a.amount
        );

    return (
      '<span class="da-el">' +
      arr
        .map(
          (e) =>
            '<span class="da-chip" title="' +
            e.label +
            ': ' +
            daFmt(e.amount) +
            '">' +
            e.label.slice(
              0,
              3
            ) +
            ' ' +
            e.pct +
            '%</span>'
        )
        .join('') +
      '</span>'
    );
  }

  function daName(id) {
    return (
      daState.names.get(id) ||
      (
        id === 0
          ? 'Desconhecido'
          : 'Player #' + id
      )
    );
  }

  function daProject() {
    const hasParty =
      daState.partyIds &&
      daState.partyIds.size >
        0;

    const hasNames =
      daState.names &&
      daState.names.size >
        0;

    let rows = [
      ...daState.entities.values(),
    ].filter(
      (b) =>
        daIdOk(b.id)
    );

    if (hasParty) {
      rows =
        rows.filter(
          (b) =>
            daState.partyIds.has(
              b.id
            )
        );
    } else if (hasNames) {
      rows =
        rows.filter(
          (b) =>
            daState.names.has(
              b.id
            )
        );
    } else {
      rows =
        rows
          .filter(
            (b) =>
              b.id <= 32 &&
              (
                b.dealtSum > 0 ||
                b.takenSum > 0
              )
          )
          .sort(
            (a, b) =>
              (
                b.dealtSum +
                b.takenSum
              ) -
              (
                a.dealtSum +
                a.takenSum
              )
          )
          .slice(
            0,
            8
          );
    }

    return rows
      .map(
        (b) => ({
          id: b.id,
          name:
            daName(b.id),

          dealtSum:
            b.dealtSum,

          dealtMax:
            b.dealtMax,

          dealtDps:
            daDps(
              b.dealtSum
            ),

          dealtHits:
            b.dealtHits,

          takenSum:
            b.takenSum,

          takenMax:
            b.takenMax,

          takenDps:
            daDps(
              b.takenSum
            ),

          takenHits:
            b.takenHits,

          dealtEl:
            b.dealtEl,

          takenEl:
            b.takenEl,
        })
      )
      .sort(
        (a, b) =>
          b.dealtSum -
          a.dealtSum ||
          b.takenSum -
          a.takenSum
      );
  }

  function daReset() {
    const names =
      daState.names;

    const partyIds =
      daState.partyIds;

    daState =
      daCreateState();

    daState.names =
      names;

    daState.partyIds =
      partyIds;

    try { sessionStorage.removeItem(DA_SESSION_KEY); } catch (_) {}
    daSchedulePaint();
  }

  function daSchedulePaint() {
    if (daPaintQueued) {
      return;
    }

    daPaintQueued =
      true;

    requestAnimationFrame(
      () => {
        daPaintQueued =
          false;

        daPaint();
      }
    );
  }

  function daMountPanel() {
    if (
      document.getElementById(
        DA_HOST
      )
    ) {
      return;
    }

    const host =
      document.createElement(
        'div'
      );

    host.id =
      DA_HOST;

    host.style.cssText =
      'position:fixed;' +
      'right:12px;' +
      'bottom:12px;' +
      'width:390px;' +
      'max-width:50vw;' +
      'z-index:99998;';

    const shadow =
      host.attachShadow({
        mode: 'open',
      });

    const style =
      document.createElement(
        'style'
      );

    style.textContent =
      DA_CSS;

    shadow.appendChild(
      style
    );

    const root =
      document.createElement(
        'div'
      );

    root.className =
      'da-root';

    shadow.appendChild(
      root
    );

    (
      document.body ||
      document.documentElement
    ).appendChild(
      host
    );

    daPaint();
  }
    // =====================================================================
  // PARSER REAL DOS FRAMES SG
  // =====================================================================

  function daB64(b64) {
    const bin = atob(b64);

    const out =
      new Uint8Array(
        bin.length
      );

    for (
      let i = 0;
      i < bin.length;
      i++
    ) {
      out[i] =
        bin.charCodeAt(i);
    }

    return out;
  }

  function daCaptureFrame(opcode, b64, source) {
    if (!daCapture.active) {
      return;
    }

    if (opcode !== 0x1c && opcode !== 0x19 && opcode !== 0x12) {
      return;
    }

    if (daCapture.frames.length >= DA_CAPTURE_MAX_FRAMES) {
      daCapture.active = false;
      daState.lastErr = 'limite de captura atingido';
      return;
    }

    daCapture.frames.push({
      at: Date.now(),
      opcode,
      source,
      b64,
    });
  }

  function daExportCapture() {
    if (daCapture.frames.length === 0) {
      return;
    }

    const payload = {
      format: 'cap-damage-capture-v1',
      capturedAt: new Date().toISOString(),
      startedAt: daCapture.startedAt,
      names: [...daState.names.entries()],
      partyIds: [...daState.partyIds],
      frames: daCapture.frames,
    };

    const url = URL.createObjectURL(
      new Blob([JSON.stringify(payload)], { type: 'application/json' })
    );

    const link = document.createElement('a');
    link.href = url;
    link.download = 'cap-damage-capture-' + Date.now() + '.json';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }

  function DaReader(buf) {
    this.b = buf;
    this.o = 0;
  }

  DaReader.prototype.rem =
    function () {
      return (
        this.b.length -
        this.o
      );
    };

  DaReader.prototype.u8 =
    function () {
      if (
        this.o >=
        this.b.length
      ) {
        throw new Error(
          'EOF u8'
        );
      }

      return this.b[
        this.o++
      ];
    };

  DaReader.prototype.i8 =
    function () {
      const v =
        this.u8();

      return (
        v > 0x7f
          ? v - 0x100
          : v
      );
    };

  DaReader.prototype.u16 =
    function () {
      if (
        this.rem() < 2
      ) {
        throw new Error(
          'EOF u16'
        );
      }

      const v =
        this.b[this.o] |
        (
          this.b[
            this.o + 1
          ] << 8
        );

      this.o += 2;

      return v;
    };

  DaReader.prototype.bytes =
    function (n) {
      if (
        this.rem() < n
      ) {
        throw new Error(
          'EOF bytes'
        );
      }

      const out =
        this.b.slice(
          this.o,
          this.o + n
        );

      this.o += n;

      return out;
    };

  DaReader.prototype.str =
    function () {
      const len =
        this.u16();

      if (
        len < 0 ||
        len > 4096 ||
        this.rem() < len
      ) {
        throw new Error(
          'string inválida'
        );
      }

      return new TextDecoder()
        .decode(
          this.bytes(len)
        );
    };

  // kind -> elemento.
  // Mantemos a mesma convenção utilizada
  // pelo Analyzer anterior.
  function daElementFromKind(
    kind
  ) {
    return (
      (kind >> 8) &
      0xff
    );
  }

  // ---------------------------------------------------------------------
  // 0x1c
  //
  // Estrutura observada nos frames reais:
  //
  // SG
  // opcode 0x1c
  // stringCount
  // strings[]
  // ...
  // registros de combate
  //
  // Nos frames capturados, cada registro F8 observado
  // possui a área necessária para extrair:
  //
  // kind
  // amount
  // attacker/id
  //
  // Não tentamos interpretar bytes desconhecidos
  // além do necessário.
  // ---------------------------------------------------------------------

  function daParse1c(
    buf
  ) {
    const r =
      new DaReader(buf);

    const result = {
      skill: '',
      strings: [],
      dealtHits: [],
      takenHits: [],
    };

    try {
      // SG + tamanho + opcode
      if (
        r.rem() < 4
      ) {
        return result;
      }

      if (
        r.u8() !== 0x53 ||
        r.u8() !== 0x47
      ) {
        return result;
      }

      r.u8();

      const op =
        r.u8();

      if (
        op !== 0x1c
      ) {
        return result;
      }

      if (
        r.rem() < 1
      ) {
        return result;
      }

      const stringCount =
        r.u8();

      if (
        stringCount >
        64
      ) {
        throw new Error(
          'stringCount inválido'
        );
      }

      for (
        let i = 0;
        i < stringCount;
        i++
      ) {
        result.strings.push(
          r.str()
        );
      }

      // Pela captura real:
      // a primeira string é o nome da ação/skill.
      result.skill =
        (
          result.strings[0] ||
          ''
        ).trim();

      daState.lastSpellStrings =
        result.strings.slice(
          0,
          32
        );

      // -----------------------------------------------------------------
      // A partir daqui percorremos os registros conhecidos.
      //
      // Não assumimos que todo byte restante é dano.
      // Procuramos apenas estruturas F8 válidas.
      // -----------------------------------------------------------------

      while (
        r.rem() >= 13
      ) {
        const start =
          r.o;

        const tag =
          r.u8();

        // ---------------------------------------------------------------
        // HIT CAUSADO
        // ---------------------------------------------------------------
        if (
          tag === 0xf8 ||
          tag === 0x78
        ) {
          if (
            r.rem() < 12
          ) {
            r.o =
              start;

            break;
          }

          const kind =
            r.u16();

          const amount =
            r.u16();

          // Dois campos posicionais/auxiliares.
          r.i8();
          r.i8();

          // Duas referências/IDs.
          const ref1 =
            r.u16();

          const ref2 =
            r.u16();

          // Identificador do atacante.
          const attacker =
            r.u8();

          // Há frames nos quais existe ainda um byte
          // auxiliar imediatamente após o atacante.
          //
          // Não o utilizamos para calcular dano; apenas
          // avançamos se ele fizer parte do registro.
          if (
            r.rem() > 0
          ) {
            r.u8();
          }

          if (
            amount > 0
          ) {
            result.dealtHits.push({
              runtimePlayerId:
                attacker || 0,

              asDealt: true,

              amount,

              element:
                daElementFromKind(
                  kind
                ),

              skill:
                result.skill,

              kind,

              ref1,
              ref2,
            });
          }

          continue;
        }

        // ---------------------------------------------------------------
        // HIT RECEBIDO
        // ---------------------------------------------------------------
        if (
          tag >= 0x80 &&
          tag <= 0x87
        ) {
          if (
            r.rem() < 7
          ) {
            r.o =
              start;

            break;
          }

          const kind =
            r.u16();

          const amount =
            r.u16();

          r.i8();
          r.i8();

          const runtimePlayerId =
            r.u8();

          if (
            amount > 0
          ) {
            result.takenHits.push({
              runtimePlayerId,

              asTaken: true,

              amount,

              element:
                daElementFromKind(
                  kind
                ),

              skill:
                result.skill,

              kind,
            });
          }

          continue;
        }

        // ---------------------------------------------------------------
        // Não reconhecido.
        //
        // Avançar 1 byte é proposital: queremos tentar
        // encontrar o próximo registro conhecido sem
        // inventar uma estrutura para o restante.
        // ---------------------------------------------------------------

        r.o =
          start + 1;
      }

    } catch (e) {
      daState.lastErr =
        String(
          e &&
          e.message
            ? e.message
            : e
        ).slice(
          0,
          100
        );
    }

    return result;
  }

  // ---------------------------------------------------------------------
  // REGISTRO DAS SKILLS
  // ---------------------------------------------------------------------

  function daRecordSkill(
    result
  ) {
    if (
      !result ||
      !result.skill
    ) {
      return;
    }

    const skill =
      daEnsureSkill(
        result.skill
      );

    if (!skill) {
      return;
    }

    // Um frame 0x1c representa uma ocorrência
    // da ação observada.
    const now =
      daNow();

    if (daState.startedAt == null) {
      daState.startedAt = now;
    }

    daState.updatedAt = now;

    const CAST_DEDUPE_MS = 500;

    const isDuplicateCast =
      skill.lastCastAt != null &&
      now - skill.lastCastAt < CAST_DEDUPE_MS;

    if (!isDuplicateCast) {
      skill.casts++;
      skill.lastCastAt = now;
    }

    skill.lastAt = now;

    for (
      const h
      of result.dealtHits
    ) {
      if (
        !(h.amount > 0)
      ) {
        continue;
      }

      skill.hits++;
      skill.damage +=
        h.amount;
    }

    daScheduleSave();
  }

  // ---------------------------------------------------------------------
  // DADOS DE COMBATE 0x19 / 0x12
  //
  // Mantemos um parser conservador para o dano
  // por personagem.
  // ---------------------------------------------------------------------

  function daParseCombatFrame(
    buf
  ) {
    const r =
      new DaReader(buf);

    const result = {
      dealtHits: [],
      takenHits: [],
    };

    try {
      if (
        r.rem() < 4
      ) {
        return result;
      }

      if (
        r.u8() !== 0x53 ||
        r.u8() !== 0x47
      ) {
        return result;
      }

      r.u8();

      const op =
        r.u8();

      if (
        op !== 0x19 &&
        op !== 0x12
      ) {
        return result;
      }

      // ---------------------------------------------------------------
      // 0x19 e 0x12 têm formatos diferentes dependendo
      // do evento. O parser abaixo procura estruturas
      // confirmadas sem usar fallback heurístico para
      // criar dano inexistente.
      // ---------------------------------------------------------------

      while (
        r.rem() >= 8
      ) {
        const start =
          r.o;

        const tag =
          r.u8();

        if (
          tag >= 0x80 &&
          tag <= 0x87
        ) {
          if (
            r.rem() < 7
          ) {
            r.o =
              start;

            break;
          }

          const kind =
            r.u16();

          const amount =
            r.u16();

          r.i8();
          r.i8();

          const runtimePlayerId =
            r.u8();

          if (
            amount > 0
          ) {
            result.takenHits.push({
              runtimePlayerId,

              asTaken: true,

              amount,

              element:
                daElementFromKind(
                  kind
                ),

              kind,
            });
          }

          continue;
        }

        if (
          tag === 0xf8 ||
          tag === 0x78
        ) {
          if (
            r.rem() < 12
          ) {
            r.o =
              start;

            break;
          }

          const kind =
            r.u16();

          const amount =
            r.u16();

          r.i8();
          r.i8();

          r.u16();
          r.u16();

          const attacker =
            r.u8();

          if (
            r.rem() > 0
          ) {
            r.u8();
          }

          if (
            amount > 0
          ) {
            result.dealtHits.push({
              runtimePlayerId:
                attacker || 0,

              asDealt: true,

              amount,

              element:
                daElementFromKind(
                  kind
                ),

              kind,
            });
          }

          continue;
        }

        // Formatos simples observados
        // em eventos de combate.
        if (
          tag <= 0x07
        ) {
          if (
            r.rem() < 7
          ) {
            r.o =
              start;

            break;
          }

          const kind =
            r.u16();

          const amount =
            r.u16();

          r.i8();
          r.i8();

          const runtimePlayerId =
            r.u8();

          if (
            amount > 0
          ) {
            result.takenHits.push({
              runtimePlayerId,

              amount,

              element:
                daElementFromKind(
                  kind
                ),

              kind,
            });
          }

          continue;
        }

        r.o =
          start + 1;
      }

    } catch (e) {
      daState.lastErr =
        String(
          e &&
          e.message
            ? e.message
            : e
        ).slice(
          0,
          100
        );
    }

    return result;
  }

  // ---------------------------------------------------------------------
  // PROCESSAMENTO OFICIAL DOS FRAMES
  // ---------------------------------------------------------------------

  function daHandleFrame(
    opcode,
    b64,
    source
  ) {
    // ---------------------------------------------------------------
    // MUITO IMPORTANTE:
    //
    // o bridge envia o mesmo frame como:
    //
    //   tipo = "sg"
    //   tipo = "combate"
    //
    // O Analyzer oficial só aceita "combate".
    //
    // Isso evita contar duas vezes o mesmo dano.
    // ---------------------------------------------------------------

    if (
      source !== 'combate'
    ) {
      daState.ignoredSgFrames++;
      return;
    }

    let buf;

    try {
      buf =
        daB64(
          String(b64)
        );
    } catch (e) {
      daState.invalidFrames++;

      daState.lastErr =
        'Base64 inválido';

      daSchedulePaint();

      return;
    }

    daState.frames++;

    daState.lastLen =
      buf.length;

    daState.lastOp =
      opcode;

    daCaptureFrame(opcode, b64, source);

    if (
      opcode === 0x1c
    ) {
      const parsed =
        daParse1c(
          buf
        );

      if (
        parsed.skill
      ) {
        daRecordSkill(
          parsed
        );
      }

      if (
        parsed.dealtHits.length ||
        parsed.takenHits.length
      ) {
        daRecord(
          [
            ...parsed.dealtHits,
            ...parsed.takenHits,
          ],
          '0x1c'
        );
      }

      if (
        parsed.skill
      ) {
        daState.parsedFrames++;
        daState.lastErr =
          null;

        daSchedulePaint();

        return;
      }

      daState.invalidFrames++;
      daState.lastErr =
        '0x1c sem skill';

      daSchedulePaint();

      return;
    }

    if (
      opcode === 0x19 ||
      opcode === 0x12
    ) {
      const parsed =
        daParseCombatFrame(
          buf
        );

      const hits = [
        ...parsed.dealtHits,
        ...parsed.takenHits,
      ];

      if (
        hits.length
      ) {
        daState.parsedFrames++;
        daState.lastErr =
          null;

        daRecord(
          hits,
          '0x' +
          opcode.toString(16)
        );
      } else {
        daState.invalidFrames++;

        daState.lastErr =
          'frame sem hit confirmado';
      }

      daSchedulePaint();

      return;
    }

    daState.invalidFrames++;

    daState.lastErr =
      'opcode não suportado';

    daSchedulePaint();
  }
    // =====================================================================
  // INTERFACE DO DAMAGE ANALYZER
  // =====================================================================

  function daPaint() {
    const host =
      document.getElementById(
        DA_HOST
      );

    if (
      !host ||
      !host.shadowRoot
    ) {
      return;
    }

    const root =
      host.shadowRoot.querySelector(
        '.da-root'
      );

    if (!root) {
      return;
    }

    const rows =
      daProject();

    const elapsed =
      daState.startedAt != null &&
      daState.updatedAt != null
        ? (
            daState.updatedAt -
            daState.startedAt
          ) / 1000
        : 0;

    const skills =
      [
        ...daState.skills.values(),
      ]
        .sort(
          (a, b) =>
            b.damage -
            a.damage
        )
        .slice(
          0,
          12
        );

    const status =
      'v2.0.0' +
      ' · tempo ' +
      Math.floor(
        elapsed
      ) +
      's' +
      ' · frames ' +
      daState.frames +
      ' · parsed ' +
      daState.parsedFrames +
      ' · hits ' +
      daState.confirmedHits +
      ' · skills ' +
      daState.skills.size +
      ' · sg ignorados ' +
      daState.ignoredSgFrames +
      ' · inválidos ' +
      daState.invalidFrames +
      (
        daState.lastOp != null
          ? ' · op 0x' +
            daState.lastOp.toString(
              16
            )
          : ''
      ) +
      (
        daState.lastLen
          ? ' · ' +
            daState.lastLen +
            'B'
          : ''
      ) +
      (
        daState.lastErr
          ? ' · ' +
            daState.lastErr
          : ''
      );

    // ---------------------------------------------------------------
    // PLAYERS
    // ---------------------------------------------------------------

    const playerHtml =
      rows.length === 0
        ? (
            '<div class="da-empty">' +
            'Aguardando combate…' +
            '</div>'
          )
        : (
            '<div class="da-list">' +

            '<div class="da-head player-head">' +
            '<span>Player</span>' +
            '<span>Dealt</span>' +
            '<span>Taken</span>' +
            '</div>' +

            rows
              .map(
                (r) =>
                  '<div class="da-row">' +

                  '<div class="da-name" title="' +
                  r.name +
                  '">' +
                  r.name +
                  '</div>' +

                  '<div class="da-metric">' +

                  '<div class="da-sum">' +
                  daFmt(
                    r.dealtSum
                  ) +
                  '</div>' +

                  '<div class="da-dps">' +
                  daFmt(
                    r.dealtDps
                  ) +
                  ' DPS</div>' +

                  '<div class="da-dps">' +
                  daFmt(
                    r.dealtMax
                  ) +
                  ' BURST 1s</div>' +

                  '<div class="da-dps">' +
                  r.dealtHits +
                  ' hits</div>' +

                  daElChips(
                    r.dealtEl,
                    r.dealtSum
                  ) +

                  '</div>' +

                  '<div class="da-metric">' +

                  '<div class="da-sum taken">' +
                  daFmt(
                    r.takenSum
                  ) +
                  '</div>' +

                  '<div class="da-dps">' +
                  daFmt(
                    r.takenDps
                  ) +
                  ' DPS</div>' +

                  '<div class="da-dps">' +
                  daFmt(
                    r.takenMax
                  ) +
                  ' BURST 1s</div>' +

                  '<div class="da-dps">' +
                  r.takenHits +
                  ' hits</div>' +

                  daElChips(
                    r.takenEl,
                    r.takenSum
                  ) +

                  '</div>' +

                  '</div>'
              )
              .join('') +

            '</div>'
          );

    // ---------------------------------------------------------------
    // SKILLS
    // ---------------------------------------------------------------

    const skillHtml =
      skills.length === 0
        ? (
            '<div class="da-empty small">' +
            'Nenhuma skill observada ainda.' +
            '</div>'
          )
        : (
            '<div class="da-skill-list">' +

            '<div class="da-skill-head">' +
            '<span>Skill</span>' +
            '<span>Cast</span>' +
            '<span>Hits</span>' +
            '<span>Dano</span>' +
            '<span>DPS</span>' +
            '</div>' +

            skills
              .map(
                (s) =>
                  '<div class="da-skill-row">' +

                  '<div class="da-skill-name" title="' +
                  s.name +
                  '">' +
                  s.name +
                  '</div>' +

                  '<div class="da-skill-num">' +
                  s.casts +
                  '</div>' +

                  '<div class="da-skill-num">' +
                  s.hits +
                  '</div>' +

                  '<div class="da-skill-damage">' +
                  daFmt(
                    s.damage
                  ) +
                  '</div>' +

                  '<div class="da-skill-dps">' +
                  daFmt(
                    daSkillDps(
                      s.damage
                    )
                  ) +
                  '</div>' +

                  '</div>'
              )
              .join('') +

            '</div>'
          );

    root.innerHTML =
      '<div class="da-panel ' +
      (
        daCollapsed
          ? 'collapsed'
          : ''
      ) +
      '">' +

      '<header>' +

      '<button type="button" class="da-toggle">' +
      '<span class="da-title">' +
      'Damage Analyzer v2' +
      '</span>' +
      '</button>' +

      '<button type="button" class="da-reset">' +
      'Reset' +
      '</button>' +

      '<button type="button" class="da-capture">' +
      (daCapture.active ? 'Parar' : 'Capturar') +
      '</button>' +

      '<button type="button" class="da-export"' +
      (daCapture.frames.length === 0 ? ' disabled' : '') +
      '>' +
      'Exportar (' + daCapture.frames.length + ')' +
      '</button>' +

      '</header>' +

      '<div class="da-body">' +

      '<section class="da-section">' +
      '<div class="da-section-title">' +
      'DANO POR PLAYER' +
      '</div>' +
      playerHtml +
      '</section>' +

      '<section class="da-section">' +
      '<div class="da-section-title">' +
      'DANO POR SKILL' +
      '</div>' +
      skillHtml +
      '</section>' +

      '<div class="da-status">' +
      status +
      '</div>' +

      '</div>' +

      '</div>';

    const toggle =
      root.querySelector(
        '.da-toggle'
      );

    if (toggle) {
      toggle.addEventListener(
        'click',
        () => {
          daCollapsed =
            !daCollapsed;

          localStorage.setItem(
            'cap-da-collapsed',
            daCollapsed
              ? '1'
              : '0'
          );

          daPaint();
        }
      );
    }

    const reset =
      root.querySelector(
        '.da-reset'
      );

    if (reset) {
      reset.addEventListener(
        'click',
        () => {
          daReset();
        }
      );
    }

    const capture = root.querySelector('.da-capture');

    if (capture) {
      capture.addEventListener('click', () => {
        if (daCapture.active) {
          daCapture.active = false;
        } else {
          daCapture.active = true;
          daCapture.startedAt = new Date().toISOString();
          daCapture.frames = [];
        }

        daPaint();
      });
    }

    const exportButton = root.querySelector('.da-export');

    if (exportButton) {
      exportButton.addEventListener('click', daExportCapture);
    }
  }

